Repository: Know Meet (React 19 web meeting app on LiveKit). Diff base: main; head: 11ecd347 (branch feat/web-conferencing-features). This is packet 6 of 7, feature area: recordings library UI, room recording UI and wiring. Other areas are reviewed in separate packets; do not report a defect solely because code referenced from another area is not shown.

Acceptance criteria (phase goals). Participants can: share a screen and stop; send chat to everyone or privately to one participant; blur or replace their background; pick microphone, camera and speaker with levels and preview, before and during a meeting; get an "Enable audio" prompt when autoplay is blocked. Local history (PGlite idb://) and local recordings stay on the device. Recording needs consent. Secrets stay server-side and clients get short-lived tokens. No `any` in TypeScript. Tauri calls are guarded by isTauri(). Flat UI with no borders, outlines or strokes; WCAG 2.2 AA.

Review the following unified diff:

diff --git a/apps/web/src/app/recordings/compose-recordings.ts b/apps/web/src/app/recordings/compose-recordings.ts
new file mode 100644
index 00000000..8db78a8e
--- /dev/null
+++ b/apps/web/src/app/recordings/compose-recordings.ts
@@ -0,0 +1,36 @@
+// TJ-ARCH-MOB-001 compliant
+import { readStoragePersisted, requestStoragePersistence } from "../../infrastructure/history";
+import {
+  type CompositeRecorder,
+  createCompositeRecorder,
+  createRecordingChangeBus,
+  createRecordingIndex,
+  createRecordingLibrary,
+} from "../../infrastructure/recording";
+import type { HistoryServices } from "../history/history-services";
+import type { RecordingsServices } from "./recordings-services";
+
+/**
+ * Local recordings (wc10): files in OPFS, their index in the local history database.
+ * Nothing opens until the first read or recording, so a tab that never records or opens
+ * the library never loads the database or touches the file system. Composed once.
+ */
+export function composeRecordings(history: HistoryServices): RecordingsServices {
+  const changes = createRecordingChangeBus();
+  const index = createRecordingIndex({ openDatabase: history.openDatabase, changes });
+  let recorder: CompositeRecorder | null = null;
+  const library = createRecordingLibrary({
+    index,
+    changes,
+    localActiveId: () => recorder?.activeRequestId() ?? null,
+    isPersisted: readStoragePersisted,
+    requestPersistence: requestStoragePersistence,
+  });
+  return {
+    library,
+    createRecorder: (room, roomCode) => {
+      recorder = createCompositeRecorder({ room, index, roomCode });
+      return recorder;
+    },
+  };
+}
