+++ b/apps/web/src/app/recordings/hooks/use-delete-recording.ts
@@ -0,0 +1,38 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RecordingRequestId } from "@know-meet/domain";
+import { useEntityMutation } from "@prometheus-ags/entity-graph-react";
+import { RECORDING_ENTITY } from "../../../infrastructure/entities/recording-entity-types";
+import type { LocalRecording } from "../../../infrastructure/recording";
+import { useAppServices } from "../../app-services";
+
+export interface DeleteRecording {
+  /**
+   * Resolves true once the file and its row are gone. False when it could not be deleted;
+   * `error` is then `recording-in-progress` (still being recorded) or `recordings-failed`.
+   */
+  readonly deleteRecording: (id: RecordingRequestId) => Promise<boolean>;
+  readonly pending: boolean;
+  readonly error: string | null;
+}
+
+/**
+ * Deletes one recording permanently. The list drops it through the library's change
+ * notice, in this tab and in every other. The caller confirms with the person first; this
+ * does not. Meetings in history that link to it keep the link and show it as gone.
+ */
+export function useDeleteRecording(): DeleteRecording {
+  const { recordings } = useAppServices();
+  const mutation = useEntityMutation<RecordingRequestId, true, LocalRecording>({
+    type: RECORDING_ENTITY,
+    mutate: async (id) => {
+      const removed = await recordings.library.remove(id);
+      if (!removed.ok) throw new Error(removed.error.code);
+      return true;
+    },
+  });
+  return {
+    deleteRecording: async (id) => (await mutation.mutate(id)) === true,
+    pending: mutation.state.isPending,
+    error: mutation.state.error,
+  };
+}
diff --git a/apps/web/src/app/recordings/hooks/use-recording-playback.ts b/apps/web/src/app/recordings/hooks/use-recording-playback.ts
new file mode 100644
index 00000000..79654ec6
--- /dev/null
+++ b/apps/web/src/app/recordings/hooks/use-recording-playback.ts
@@ -0,0 +1,68 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RecordingRequestId } from "@know-meet/domain";
+import { useEffect, useState } from "react";
+import type { PlaybackSource } from "../../../infrastructure/recording";
+import { useAppServices } from "../../app-services";
+
+/**
+ * - `idle`: no recording selected.
+ * - `loading`: opening the file.
+ * - `ready`: `url` plays; it is revoked when another recording is chosen or the screen unmounts.
+ * - `missing`: the file is gone (the recording can only be deleted from the list).
+ * - `recording`: a tab is still writing it; it can be played once it ends.
+ * - `failed`: opening it failed for another reason.
+ */
+export type RecordingPlayback =
+  | { readonly status: "idle" }
+  | { readonly status: "loading" }
+  | { readonly status: "ready"; readonly url: string; readonly mimeType: string }
+  | { readonly status: "missing" | "recording" | "failed" };
+
+const IDLE: RecordingPlayback = { status: "idle" };
+const LOADING: RecordingPlayback = { status: "loading" };
+
+/**
+ * Opens one recording for playback as an object URL of the OPFS file; nothing is copied or
+ * uploaded. The URL is revoked on unmount and whenever the id changes. A playback error
+ * the player itself reports (a file cut off mid-write) is the screen's to show.
+ */
+export function useRecordingPlayback(id: RecordingRequestId | null): RecordingPlayback {
+  const { recordings } = useAppServices();
+  const [state, setState] = useState<RecordingPlayback>(IDLE);
+
+  useEffect(() => {
+    if (id === null) {
+      setState(IDLE);
+      return undefined;
+    }
+    let cancelled = false;
+    let source: PlaybackSource | null = null;
+    setState(LOADING);
+    void recordings.library.openPlayback(id).then((opened) => {
+      if (cancelled) {
+        if (opened.ok) opened.value.revoke();
+        return;
+      }
+      if (opened.ok) {
+        source = opened.value;
+        setState({ status: "ready", url: opened.value.url, mimeType: opened.value.mimeType });
+        return;
+      }
+      const code = opened.error.code;
+      setState({
+        status:
+          code === "recording-file-missing"
+            ? "missing"
+            : code === "recording-in-progress"
+              ? "recording"
+              : "failed",
+      });
+    });
+    return () => {
+      cancelled = true;
+      source?.revoke();
+    };
+  }, [recordings, id]);
+
+  return state;
+}
diff --git a/apps/web/src/app/recordings/hooks/use-recording-storage.ts b/apps/web/src/app/recordings/hooks/use-recording-storage.ts
