@@ -0,0 +1,43 @@
+// TJ-ARCH-MOB-001 compliant
+import { useEntityMutation, useEntityQuery } from "@prometheus-ags/entity-graph-react";
+import {
+  RECORDING_STORAGE_ENTITY,
+  RECORDING_STORAGE_ROW_ID,
+  type RecordingStorageRow,
+} from "../../../infrastructure/entities/recording-entity-types";
+import { useAppServices } from "../../app-services";
+
+export interface RecordingStorage {
+  /** Null until the first read finishes. */
+  readonly info: RecordingStorageRow | null;
+  /**
+   * Asks the browser to keep recordings (`navigator.storage.persist()`, the "Keep
+   * recordings" action); `info.persisted` follows. Call it from a click.
+   */
+  readonly requestPersistence: () => Promise<void>;
+  readonly requesting: boolean;
+}
+
+/**
+ * Space used and available for recordings, and whether the browser may clear them under
+ * pressure. For the screen's storage notice and its "Keep recordings" action.
+ */
+export function useRecordingStorage(): RecordingStorage {
+  const { recordings } = useAppServices();
+  const query = useEntityQuery<RecordingStorageRow>(RECORDING_STORAGE_ENTITY);
+  const mutation = useEntityMutation<void, RecordingStorageRow, RecordingStorageRow>({
+    type: RECORDING_STORAGE_ENTITY,
+    mutate: async () => ({
+      id: RECORDING_STORAGE_ROW_ID,
+      ...(await recordings.library.requestPersistence()),
+    }),
+    normalize: (row) => ({ id: row.id, data: row }),
+  });
+  return {
+    info: query.items[0] ?? null,
+    requestPersistence: async () => {
+      await mutation.mutate();
+    },
+    requesting: mutation.state.isPending,
+  };
+}
diff --git a/apps/web/src/app/recordings/hooks/use-recordings.ts b/apps/web/src/app/recordings/hooks/use-recordings.ts
new file mode 100644
index 00000000..2eca0d8a
--- /dev/null
+++ b/apps/web/src/app/recordings/hooks/use-recordings.ts
@@ -0,0 +1,39 @@
+// TJ-ARCH-MOB-001 compliant
+import type { Support } from "@know-meet/domain";
+import { useEntityQuery } from "@prometheus-ags/entity-graph-react";
+import { RECORDING_ENTITY } from "../../../infrastructure/entities/recording-entity-types";
+import type { LocalRecording } from "../../../infrastructure/recording";
+import { useAppServices } from "../../app-services";
+
+export interface Recordings {
+  /** Every recording kept on this device, newest first. */
+  readonly recordings: readonly LocalRecording[];
+  /** True while the first read runs and nothing is shown yet. */
+  readonly loading: boolean;
+  /** Set when reading failed; a browser without file storage is `support`, not an error. */
+  readonly error: string | null;
+  /** `unsupported`: this browser cannot keep recordings; show the unsupported state. */
+  readonly support: Support;
+  /**
+   * Reads again. Use it when the screen opens: a recording whose tab died has no change
+   * to announce, so only a read shows it turned from "recording" into "incomplete".
+   */
+  readonly reload: () => void;
+}
+
+/**
+ * The recordings library list, kept current when a recording starts, ends or is deleted
+ * in this tab or any other. Each row has a `state`: recording, complete, stopped-early
+ * (storage was full), incomplete, or missing (its file is gone).
+ */
+export function useRecordings(): Recordings {
+  const { recordings } = useAppServices();
+  const query = useEntityQuery<LocalRecording>(RECORDING_ENTITY);
+  return {
+    recordings: [...query.items].sort((a, b) => b.startedAt - a.startedAt),
+    loading: query.isLoading,
+    error: query.error?.message ?? null,
+    support: recordings.library.support,
+    reload: query.refetch,
+  };
+}
diff --git a/apps/web/src/app/recordings/hooks/use-room-recording.ts b/apps/web/src/app/recordings/hooks/use-room-recording.ts
new file mode 100644
index 00000000..bb9cc33e
--- /dev/null
+++ b/apps/web/src/app/recordings/hooks/use-room-recording.ts
@@ -0,0 +1,69 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RecordRequestError } from "@know-meet/application";
+import {
+  type ConsentAnswer,
+  type ConsentNotice,
+  type ConsentPrompt,
+  consentPrompt,
+  isRecordingIndicatorOn,
+  type RecordingConsentState,
+  type Result,
+  type Support,
+} from "@know-meet/domain";
+import { useMemo, useSyncExternalStore } from "react";
+import { useAppServices } from "../../app-services";
+
+export interface RoomRecordingView {
+  /** The whole consent state, for exhaustive screens. */
+  readonly state: RecordingConsentState;
+  /** The question this participant must answer now, or null. Show a prompt when set. */
+  readonly prompt: ConsentPrompt | null;
+  /** True while a recording runs or starts anywhere in the room: show the indicator. */
+  readonly indicatorOn: boolean;
+  /** True while this device is the one recording (offer "Stop recording"). */
+  readonly recordingHere: boolean;
+  /** True while this participant's own request waits for answers (offer "Cancel request"). */
+  readonly requesting: boolean;
+  /** One-time notice (declined, not sent, recorder failed, stopped); clear it with `dismissNotice`. */
+  readonly notice: ConsentNotice | null;
+  /** `unsupported`: hide or explain the request control; it would fail. */
+  readonly support: Support;
+  readonly request: () => Result<void, RecordRequestError>;
+  readonly answer: (answer: ConsentAnswer) => void;
+  readonly withdraw: () => void;
+  readonly stop: () => void;
+  readonly dismissNotice: () => void;
+}
+
+/**
+ * Recording consent for the meeting the page is in (WC-8, WC-9, decision D2): request,
+ * answer the prompt (including a late joiner's, which stops the recording for everyone
+ * when declined), the indicator, stop, and notices. Outside a meeting the state is idle
+ * and the actions do nothing.
+ */
+export function useRoomRecording(): RoomRecordingView {
+  const { meeting } = useAppServices();
+  const { recording } = meeting;
+  const state = useSyncExternalStore(
+    recording.subscribe,
+    recording.getSnapshot,
+    recording.getSnapshot,
+  );
+  return useMemo(
+    () => ({
+      state,
+      prompt: consentPrompt(state),
+      indicatorOn: isRecordingIndicatorOn(state),
+      recordingHere: state.status === "local-starting" || state.status === "local-recording",
+      requesting: state.status === "requesting",
+      notice: state.status === "idle" ? state.notice : null,
+      support: recording.support,
+      request: recording.request,
+      answer: recording.answer,
+      withdraw: recording.withdraw,
+      stop: recording.stop,
+      dismissNotice: recording.dismissNotice,
+    }),
+    [state, recording],
+  );
+}
diff --git a/apps/web/src/app/recordings/new-recording-request-id.ts b/apps/web/src/app/recordings/new-recording-request-id.ts
new file mode 100644
index 00000000..750229ba
--- /dev/null
+++ b/apps/web/src/app/recordings/new-recording-request-id.ts
@@ -0,0 +1,19 @@
+// TJ-ARCH-MOB-001 compliant
+import { parseRecordingRequestId, type RecordingRequestId } from "@know-meet/domain";
+
+/**
+ * A fresh id for one recording request; it also names the recording's file. A UUID when
+ * the browser has one, otherwise 128 random bits in hex. Both fit the id's 8 to 64
+ * URL-safe characters.
+ */
+export function newRecordingRequestId(): RecordingRequestId {
+  const text =
+    typeof crypto.randomUUID === "function"
+      ? crypto.randomUUID()
+      : Array.from(crypto.getRandomValues(new Uint8Array(16)), (byte) =>
+          byte.toString(16).padStart(2, "0"),
+        ).join("");
+  const id = parseRecordingRequestId(text);
+  if (id === null) throw new Error("The browser produced an unusable recording id");
+  return id;
+}
