+// TJ-ARCH-MOB-001 compliant
+import type { RealtimeRoom } from "@know-meet/application";
+import type { CompositeRecorder, RecordingLibrary } from "../../infrastructure/recording";
+
+/**
+ * The recordings kept in this browser, as the app shell hands them to hooks. Screens read
+ * and delete through the hooks in `./hooks`, never through the library directly.
+ */
+export interface RecordingsServices {
+  readonly library: RecordingLibrary;
+  /**
+   * Builds the local recorder for one meeting room. `roomCode` is read when a recording
+   * starts. Call it once per page: the library asks the latest recorder what it is writing.
+   */
+  readonly createRecorder: (room: RealtimeRoom, roomCode: () => string | null) => CompositeRecorder;
+}
diff --git a/apps/web/src/app/recordings/room-recording.ts b/apps/web/src/app/recordings/room-recording.ts
new file mode 100644
index 00000000..b445f547
--- /dev/null
+++ b/apps/web/src/app/recordings/room-recording.ts
@@ -0,0 +1,99 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  createRecordingConsent,
+  type LocalRecorder,
+  type RealtimeRoom,
+  type RecordingConsent,
+  type RecordingStateSource,
+  type RecordRequestError,
+} from "@know-meet/application";
+import {
+  CONSENT_IDLE,
+  type ConsentAnswer,
+  err,
+  meetingErrors,
+  type RecordingConsentState,
+  type RecordingRequestId,
+  type Result,
+  type Support,
+} from "@know-meet/domain";
+
+/**
+ * Recording consent for the meeting the page is in, as the screens use it. The consent
+ * use cases (`createRecordingConsent`) live for one room session; this holds the current
+ * one so screens and the history recorder have a stable object to read and call across
+ * joins and leaves. Outside a session the state is idle and every action does nothing.
+ */
+export interface RoomRecording extends RecordingStateSource {
+  /** Whether this browser can record locally; hide or explain the request control when not. */
+  readonly support: Support;
+  /** Starts a consent session for the room just joined. The composition root calls it. */
+  begin(): void;
+  /** Ends the session: a recording in progress is stopped and kept. Resolves when done. */
+  end(): Promise<void>;
+  /** Asks everyone present to agree to a recording on this device. */
+  request(): Result<void, RecordRequestError>;
+  /** Answers the prompt (`consentPrompt(state)`); ignored when there is none. */
+  answer(answer: ConsentAnswer): void;
+  /** Withdraws this participant's pending request. */
+  withdraw(): void;
+  /** Stops this device's recording and keeps what was written. */
+  stop(): void;
+  /** Clears the notice (`state.notice`) once it was read. */
+  dismissNotice(): void;
+}
+
+export interface RoomRecordingPorts {
+  readonly room: RealtimeRoom;
+  readonly recorder: LocalRecorder;
+  readonly newRequestId: () => RecordingRequestId;
+}
+
+export function createRoomRecording(ports: RoomRecordingPorts): RoomRecording {
+  let consent: RecordingConsent | null = null;
+  let unsubscribe: (() => void) | null = null;
+  const listeners = new Set<() => void>();
+
+  const emit = (): void => {
+    for (const listener of [...listeners]) listener();
+  };
+
+  /** Detaches the current session and returns it so the caller can finish it. */
+  const detach = (): RecordingConsent | null => {
+    const previous = consent;
+    consent = null;
+    unsubscribe?.();
+    unsubscribe = null;
+    return previous;
+  };
+
+  return {
+    support: ports.recorder.support,
+    getSnapshot: (): RecordingConsentState => consent?.getSnapshot() ?? CONSENT_IDLE,
+    subscribe: (listener) => {
+      listeners.add(listener);
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+    begin: () => {
+      const previous = detach();
+      if (previous !== null) void previous.dispose();
+      const next = createRecordingConsent(ports);
+      consent = next;
+      unsubscribe = next.subscribe(emit);
+      emit();
+    },
+    end: async () => {
+      const previous = detach();
+      if (previous === null) return;
+      emit();
+      await previous.dispose();
+    },
+    request: () => consent?.request() ?? err(meetingErrors.connectionLost()),
+    answer: (answer) => consent?.answer(answer),
+    withdraw: () => consent?.withdraw(),
+    stop: () => consent?.stop(),
+    dismissNotice: () => consent?.dismissNotice(),
+  };
+}
diff --git a/apps/web/src/app/recordings/with-room-recording.ts b/apps/web/src/app/recordings/with-room-recording.ts
new file mode 100644
index 00000000..241b8c9b
--- /dev/null
+++ b/apps/web/src/app/recordings/with-room-recording.ts
@@ -0,0 +1,38 @@
+// TJ-ARCH-MOB-001 compliant
+import type { MeetingUseCasesWithHistory } from "../history/with-meeting-history";
+import type { RoomRecording } from "./room-recording";
+
+export interface RoomRecordingDependencies {
+  readonly recording: RoomRecording;
+  /** Told the room code after a join and null after a leave, for the recordings index. */
+  readonly setRoomCode: (code: string | null) => void;
+}
+
+/**
+ * Starts the recording consent session when a meeting is joined and ends it when the
+ * meeting is left, so no screen has to (WC-8). Leaving first ends the consent session,
+ * which stops a recording running here and tells the others while still connected. It
+ * never changes what `join` or `leave` return.
+ */
+export function withRoomRecording(
+  inner: MeetingUseCasesWithHistory,
+  dependencies: RoomRecordingDependencies,
+): MeetingUseCasesWithHistory {
+  const { recording, setRoomCode } = dependencies;
+  return {
+    ...inner,
+    join: async (request, signal) => {
+      const result = await inner.join(request, signal);
+      if (result.ok) {
+        setRoomCode(result.value.code);
+        recording.begin();
+      }
+      return result;
+    },
+    leave: async () => {
+      await recording.end();
+      setRoomCode(null);
+      await inner.leave();
+    },
+  };
+}
