+// TJ-ARCH-MOB-001 compliant
+import type { RecordingStorageInfo } from "../recording";
+
+/** Entity type names the recording transports register under. */
+export const RECORDING_ENTITY = "LocalRecording";
+export const RECORDING_STORAGE_ENTITY = "RecordingStorage";
+
+/** The one row of the RecordingStorage entity. */
+export const RECORDING_STORAGE_ROW_ID = "storage";
+
+/** What the browser says about the space recordings may use and whether it will keep them. */
+export interface RecordingStorageRow extends RecordingStorageInfo {
+  readonly id: typeof RECORDING_STORAGE_ROW_ID;
+}
diff --git a/apps/web/src/infrastructure/entities/register-recording-entities.ts b/apps/web/src/infrastructure/entities/register-recording-entities.ts
new file mode 100644
index 00000000..0d42fd20
--- /dev/null
+++ b/apps/web/src/infrastructure/entities/register-recording-entities.ts
@@ -0,0 +1,92 @@
+// TJ-ARCH-MOB-001 compliant
+import { parseRecordingRequestId } from "@know-meet/domain";
+import { registerEntityTransport } from "@prometheus-ags/entity-graph-core";
+import type { LocalRecording, RecordingLibrary } from "../recording";
+import {
+  RECORDING_ENTITY,
+  RECORDING_STORAGE_ENTITY,
+  RECORDING_STORAGE_ROW_ID,
+  type RecordingStorageRow,
+} from "./recording-entity-types";
+
+/** A recordings read failed for a reason the screen shows as an error, never as an empty list. */
+export class RecordingReadError extends Error {
+  readonly code: string;
+  constructor(code: string) {
+    super(`Local recordings could not be read (${code})`);
+    this.name = "RecordingReadError";
+    this.code = code;
+  }
+}
+
+/**
+ * Registers the recording entity transports with the entity graph (wc10 task 10.3). Call
+ * it once at the runtime boundary.
+ *
+ * The list reads the library whole: a person's recordings number in the dozens, and the
+ * library has no filter or sort of its own, so the screen sorts and filters the rows in
+ * the graph. A browser without OPFS lists as empty (the screen reads RecordingStorage
+ * for the notice); a failed read throws.
+ */
+export function registerRecordingEntities(library: RecordingLibrary): void {
+  const known = new Set<string>();
+
+  registerEntityTransport<LocalRecording>(RECORDING_ENTITY, {
+    identify: (recording) => recording.id,
+    authoritative: true,
+    list: async (query) => {
+      const listed = await library.list(query.signal);
+      if (!listed.ok) {
+        if (listed.error.code === "recordings-unavailable") return { rows: [], total: 0 };
+        throw new RecordingReadError(listed.error.code);
+      }
+      known.clear();
+      for (const recording of listed.value) known.add(recording.id);
+      return { rows: [...listed.value], total: listed.value.length, nextCursor: null };
+    },
+    get: async (id) => {
+      const recordingId = parseRecordingRequestId(id);
+      if (recordingId === null) return null;
+      const found = await library.get(recordingId);
+      if (!found.ok) throw new RecordingReadError(found.error.code);
+      return found.value;
+    },
+    subscribe: (onChange) => {
+      let active = true;
+      const unsubscribe = library.subscribe((change) => {
+        if (change.kind === "deleted") {
+          known.delete(change.id);
+          onChange({ op: "delete", id: change.id });
+          return;
+        }
+        void library.get(change.id).then((found) => {
+          if (!active || !found.ok) return;
+          if (found.value === null) {
+            known.delete(change.id);
+            onChange({ op: "delete", id: change.id });
+            return;
+          }
+          const op = known.has(change.id) ? "update" : "insert";
+          known.add(change.id);
+          onChange({ op, id: change.id, row: found.value });
+        });
+      });
+      return () => {
+        active = false;
+        unsubscribe();
+      };
+    },
+  });
+
+  const readStorage = async (): Promise<RecordingStorageRow> => ({
+    id: RECORDING_STORAGE_ROW_ID,
+    ...(await library.storage()),
+  });
+
+  registerEntityTransport<RecordingStorageRow>(RECORDING_STORAGE_ENTITY, {
+    identify: (row) => row.id,
+    authoritative: true,
+    list: async () => ({ rows: [await readStorage()], total: 1 }),
+    get: async () => readStorage(),
+  });
+}
diff --git a/apps/web/src/presentation/local-recordings/application/recording-format.ts b/apps/web/src/presentation/local-recordings/application/recording-format.ts
new file mode 100644
index 00000000..0a6ed553
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/application/recording-format.ts
@@ -0,0 +1,175 @@
+// TJ-ARCH-MOB-001 compliant
+// Display rules for recordings saved in this browser (shape recordings-library.md §4,
+// §6, §7, RL-2): titles, dates ("18 Nov 2026 · 14:30", 24-hour), lengths, format names,
+// the download filename, sorting and the storage meter band. Pure functions over the
+// fields a library row carries; `RecordingFacts` is that shape, so the hooks' rows fit it
+// without this file knowing where they come from.
+import { formatBytes } from "../../workspace/application/format";
+
+export type RecordingCondition =
+  | "recording"
+  | "complete"
+  | "stopped-early"
+  | "incomplete"
+  | "missing";
+
+export interface RecordingFacts {
+  readonly roomCode: string | null;
+  readonly meetingTitle: string | null;
+  readonly startedAt: number;
+  readonly endedAt: number | null;
+  readonly mimeType: string;
+  readonly sizeBytes: number;
+  readonly state: RecordingCondition;
+}
+
+export type LibrarySort = "new" | "old" | "large";
+export type LibraryLayout = "grid" | "list";
+
+const MONTHS = [
+  "Jan",
+  "Feb",
+  "Mar",
+  "Apr",
+  "May",
+  "Jun",
+  "Jul",
+  "Aug",
+  "Sep",
+  "Oct",
+  "Nov",
+  "Dec",
+] as const;
+const SECOND_MS = 1000;
+const MINUTE_MS = 60 * SECOND_MS;
+
+function pad(n: number): string {
+  return n < 10 ? `0${n}` : String(n);
+}
+
+/** "14:30". */
+export function clockTime(ms: number): string {
+  const d = new Date(ms);
+  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
+}
+
+/** "18 Nov 2026". */
+export function calendarDate(ms: number): string {
+  const d = new Date(ms);
+  return `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
+}
+
+/** "Meeting 4KQ-9ZD", the history title when there is one, else a plain fallback. */
+export function recordingTitle(facts: RecordingFacts): string {
+  const title = facts.meetingTitle?.trim();
+  if (title !== undefined && title !== "") return title;
+  return facts.roomCode === null ? "Meeting recording" : `Meeting ${facts.roomCode}`;
+}
+
+/** Recorded length in ms from the start and end the recorder wrote; null when unknown. */
+export function recordedMs(facts: RecordingFacts): number | null {
+  if (facts.endedAt === null || facts.endedAt < facts.startedAt) return null;
+  return facts.endedAt - facts.startedAt;
+}
+
+/** "21 min", "45 s", or "unknown". */
+export function lengthLabel(ms: number | null): string {
+  if (ms === null) return "unknown";
+  if (ms < MINUTE_MS) return `${Math.max(1, Math.round(ms / SECOND_MS))} s`;
+  return `${Math.round(ms / MINUTE_MS)} min`;
+}
+
+/** "21 minutes", "45 seconds", "unknown length", for accessible names. */
+export function spokenLength(ms: number | null): string {
+  if (ms === null) return "unknown length";
+  if (ms < MINUTE_MS) {
+    const s = Math.max(1, Math.round(ms / SECOND_MS));
+    return `${s} ${s === 1 ? "second" : "seconds"}`;
+  }
+  const m = Math.round(ms / MINUTE_MS);
+  return `${m} ${m === 1 ? "minute" : "minutes"}`;
+}
+
+/** "MP4" or "WebM" (the container), from the MIME type the recorder wrote. */
+export function formatName(mimeType: string): string {
+  const subtype = mimeType.split(";")[0]?.split("/")[1]?.trim().toLowerCase() ?? "";
+  if (subtype === "mp4") return "MP4";
+  if (subtype === "webm") return "WebM";
+  return subtype === "" ? "Video" : subtype.toUpperCase();
+}
+
+/** "18 Nov 2026 · 14:30 · 21 min · 214 MB". */
+export function metaLine(facts: RecordingFacts): string {
+  return [
+    calendarDate(facts.startedAt),
+    clockTime(facts.startedAt),
+    lengthLabel(recordedMs(facts)),
+    formatBytes(facts.sizeBytes),
+  ].join(" · ");
+}
+
+/** "Recorded 18 Nov 2026, 14:30 · 21 min · 214 MB · MP4". */
+export function detailFacts(facts: RecordingFacts): string {
+  return [
+    `Recorded ${calendarDate(facts.startedAt)}, ${clockTime(facts.startedAt)}`,
+    lengthLabel(recordedMs(facts)),
+    formatBytes(facts.sizeBytes),
+    formatName(facts.mimeType),
+  ].join(" · ");
+}
+
+const CONDITION_WORDS: Readonly<Record<RecordingCondition, string>> = {
+  recording: "recording now",
+  complete: "",
+  "stopped-early": "stopped early",
+  incomplete: "incomplete",
+  missing: "file missing",
+};
+
+/** RL-2: "Meeting 4KQ-9ZD, 18 Nov 14:30, 21 minutes" plus any condition. */
+export function itemName(facts: RecordingFacts): string {
+  const d = new Date(facts.startedAt);
+  const parts = [
+    recordingTitle(facts),
+    `${d.getDate()} ${MONTHS[d.getMonth()]} ${clockTime(facts.startedAt)}`,
+    spokenLength(recordedMs(facts)),
+  ];
+  const condition = CONDITION_WORDS[facts.state];
+  return (condition === "" ? parts : [...parts, condition]).join(", ");
+}
+
+/** `know-meet-4KQ-9ZD-2026-11-18-1430.webm`. */
+export function downloadFilename(facts: RecordingFacts): string {
+  const d = new Date(facts.startedAt);
+  const code = (facts.roomCode ?? "recording").replace(/[^A-Za-z0-9-]/g, "");
+  const stamp = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`;
+  const extension = formatName(facts.mimeType) === "MP4" ? "mp4" : "webm";
+  return `know-meet-${code === "" ? "recording" : code}-${stamp}.${extension}`;
+}
+
+export function sortRecordings<T extends RecordingFacts>(
+  rows: readonly T[],
+  sort: LibrarySort,
+): readonly T[] {
+  const copy = [...rows];
+  if (sort === "old") return copy.sort((a, b) => a.startedAt - b.startedAt);
+  if (sort === "large") return copy.sort((a, b) => b.sizeBytes - a.sizeBytes);
+  return copy.sort((a, b) => b.startedAt - a.startedAt);
+}
+
+export type StorageBand = "ok" | "high" | "full";
+
+export interface StorageUse {
+  readonly percent: number;
+  readonly band: StorageBand;
+}
+
+const HIGH_PERCENT = 80;
+const FULL_PERCENT = 95;
+
+/** Meter value and band: under 80% ok, 80 to 95% high (amber), above 95% full (red). */
+export function storageUse(usedBytes: number, quotaBytes: number): StorageUse {
+  const percent = quotaBytes > 0 ? Math.min(100, (usedBytes / quotaBytes) * 100) : 0;
+  const band = percent > FULL_PERCENT ? "full" : percent >= HIGH_PERCENT ? "high" : "ok";
+  return { percent, band };
+}
diff --git a/apps/web/src/presentation/local-recordings/application/recordings-route.ts b/apps/web/src/presentation/local-recordings/application/recordings-route.ts
