@@ -0,0 +1,99 @@
+// TJ-ARCH-MOB-001 compliant
+// "Delete this recording?" (shape recordings-library.md §6, §7, RL-9): the kit
+// AlertDialog opened by the detail's Delete button. Focus starts on Cancel (a
+// destructive action is never the default); Escape cancels and focus returns to Delete.
+// It stays open while deleting (spinner, "Deleting...") and on failure, whose line sits
+// inside the description so `aria-describedby` reads it. On success the screen closes
+// it and moves focus itself (`returnFocus={false}`).
+import {
+  AlertDialog,
+  AlertDialogAction,
+  AlertDialogCancel,
+  AlertDialogContent,
+  AlertDialogDescription,
+  AlertDialogFooter,
+  AlertDialogHeader,
+  AlertDialogTitle,
+  AlertDialogTrigger,
+} from "@know-meet/ui/components/alert-dialog";
+import { Button } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import { useId } from "react";
+
+export const DELETE_FAILED_TEXT = "Couldn't delete. Close other Know Meet tabs and try again.";
+
+interface DeleteRecordingDialogProps {
+  readonly open: boolean;
+  readonly onOpenChange: (open: boolean) => void;
+  /** "214 MB", for "The 214 MB file is removed…". */
+  readonly size: string;
+  readonly pending: boolean;
+  readonly failed: boolean;
+  readonly returnFocus: boolean;
+  readonly onConfirm: () => void;
+}
+
+export function DeleteRecordingDialog({
+  open,
+  onOpenChange,
+  size,
+  pending,
+  failed,
+  returnFocus,
+  onConfirm,
+}: DeleteRecordingDialogProps) {
+  const cancelId = useId();
+  return (
+    <AlertDialog open={open} onOpenChange={onOpenChange}>
+      <AlertDialogTrigger render={<Button type="button" variant="destructive" />}>
+        <KmIcon name="trash" />
+        <span>Delete</span>
+      </AlertDialogTrigger>
+      <AlertDialogContent
+        initialFocus={() => document.getElementById(cancelId)}
+        finalFocus={returnFocus}
+      >
+        <AlertDialogHeader>
+          <AlertDialogTitle>Delete this recording?</AlertDialogTitle>
+          <AlertDialogDescription render={<div />}>
+            <p className="m-0">
+              The {size} file is removed from this browser. Download it first if you want to keep a
+              copy. This can't be undone.
+            </p>
+            <p aria-live="polite" className="m-0">
+              {failed && !pending ? (
+                <span className="mt-s3 flex items-start gap-s2 font-semibold text-foreground">
+                  <KmIcon name="alert" className="mt-px size-4 text-red-text" />
+                  <span>{DELETE_FAILED_TEXT}</span>
+                </span>
+              ) : null}
+            </p>
+          </AlertDialogDescription>
+        </AlertDialogHeader>
+        <AlertDialogFooter>
+          <AlertDialogCancel id={cancelId}>Cancel</AlertDialogCancel>
+          <AlertDialogAction
+            variant="destructive"
+            disabled={pending}
+            focusableWhenDisabled
+            onClick={onConfirm}
+          >
+            {pending ? (
+              <>
+                <Spinner
+                  aria-hidden="true"
+                  role="presentation"
+                  className="motion-reduce:animate-none"
+                />
+                <span>Deleting...</span>
+              </>
+            ) : (
+              "Delete recording"
+            )}
+          </AlertDialogAction>
+        </AlertDialogFooter>
+      </AlertDialogContent>
+    </AlertDialog>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/library-states.tsx b/apps/web/src/presentation/local-recordings/presentation/library-states.tsx
new file mode 100644
index 00000000..6c155182
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/library-states.tsx
@@ -0,0 +1,172 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape recordings-library.md §6 states for the library area: loading (two skeleton
+// cards after 300 ms, no shimmer), empty (with the three steps of how recording works,
+// or the "can't record" text when this browser has no recorder), storage unavailable
+// (static content with an `alert` glyph and a heading, not role="alert") and a read
+// failure (cause, then the fix).
+import { Button, buttonVariants } from "@know-meet/ui/components/button";
+import {
+  Empty,
+  EmptyContent,
+  EmptyDescription,
+  EmptyHeader,
+  EmptyMedia,
+  EmptyTitle,
+} from "@know-meet/ui/components/empty";
+import { KmIcon, type KmIconName } from "@know-meet/ui/components/km-icon";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import type * as React from "react";
+import { useEffect, useState } from "react";
+
+const SKELETON_DELAY_MS = 300;
+const SKELETON_CARDS = ["a", "b"] as const;
+
+/** True once `delayMs` passed; skeletons wait so a quick read never flashes them. */
+function useDelayedFlag(delayMs: number): boolean {
+  const [on, setOn] = useState(false);
+  useEffect(() => {
+    const timer = window.setTimeout(() => setOn(true), delayMs);
+    return () => window.clearTimeout(timer);
+  }, [delayMs]);
+  return on;
+}
+
+export function LibrarySkeleton() {
+  const visible = useDelayedFlag(SKELETON_DELAY_MS);
+  return (
+    <section
+      aria-busy="true"
+      aria-label="Loading recordings"
+      className="grid grid-cols-[repeat(auto-fill,minmax(min(100%,300px),1fr))] gap-s4"
+    >
+      {visible
+        ? SKELETON_CARDS.map((key) => (
+            <div
+              key={key}
+              aria-hidden="true"
+              className="grid overflow-hidden rounded-tile bg-surface"
+            >
+              <div className="aspect-video bg-muted" />
+              <div className="grid gap-s2 p-s4">
+                <div className="h-4 w-2/3 rounded-pill bg-muted" />
+                <div className="h-3 w-1/2 rounded-pill bg-muted" />
+              </div>
+            </div>
+          ))
+        : null}
+    </section>
+  );
+}
+
+interface Step {
+  readonly icon: KmIconName;
+  readonly title: string;
+  readonly detail?: string;
+}
+
+const STEPS: readonly Step[] = [
+  { icon: "record", title: "Ask the room" },
+  { icon: "users", title: "Everyone agrees" },
+  {
+    icon: "database",
+    title: "Saved in this browser",
+    detail: "Never uploaded. Download it to keep a copy elsewhere.",
+  },
+];
+
+const EMPTY_TEXT =
+  "Ask to record from the meeting room. Everyone is asked first, and the file is saved only in this browser.";
+const CANNOT_RECORD_TEXT =
+  "This browser can't record meetings. Recording works in current Chrome, Edge, Firefox and Safari on a computer.";
+
+export function EmptyLibrary({ canRecord }: { readonly canRecord: boolean }) {
+  return (
+    <Empty role="region" aria-labelledby="recordings-empty-h">
+      <EmptyHeader>
+        <EmptyMedia variant="icon">
+          <KmIcon name="film" />
+        </EmptyMedia>
+        <EmptyTitle render={(props) => <h2 {...props} id="recordings-empty-h" />}>
+          No recordings on this device
+        </EmptyTitle>
+        <EmptyDescription>{canRecord ? EMPTY_TEXT : CANNOT_RECORD_TEXT}</EmptyDescription>
+      </EmptyHeader>
+      {canRecord ? (
+        <ol className="grid gap-s3">
+          {STEPS.map((step) => (
+            <li key={step.title} className="grid grid-cols-[auto_minmax(0,1fr)] items-start gap-s3">
+              <span
+                aria-hidden="true"
+                className="inline-grid size-9 place-items-center rounded-10 bg-muted text-muted-foreground"
+              >
+                <KmIcon name={step.icon} className="size-4" />
+              </span>
+              <span className="grid gap-0.5 pt-1.5">
+                <strong className="text-sm font-semibold">{step.title}</strong>
+                {step.detail === undefined ? null : (
+                  <span className="text-sm text-muted-foreground">{step.detail}</span>
+                )}
+              </span>
+            </li>
+          ))}
+        </ol>
+      ) : null}
+      <EmptyContent>
+        <Link to="/" className={cn(buttonVariants(), focusFillClass)}>
+          <KmIcon name="cam" />
+          <span>Start a meeting</span>
+        </Link>
+      </EmptyContent>
+    </Empty>
+  );
+}
+
+function StaticProblem({
+  title,
+  children,
+}: {
+  readonly title: string;
+  readonly children: React.ReactNode;
+}) {
+  return (
+    <section
+      aria-labelledby="recordings-problem-h"
+      className="grid gap-s3 rounded-base bg-surface px-s5 py-s4"
+    >
+      <h2 id="recordings-problem-h" className="flex items-center gap-s2 text-base">
+        <KmIcon name="alert" className="text-red-text" />
+        <span>{title}</span>
+      </h2>
+      {children}
+    </section>
+  );
+}
+
+export function StorageUnavailable() {
+  return (
+    <StaticProblem title="Recordings aren't available in this window">
+      <p className="text-sm text-muted-foreground">
+        This browser blocked local storage, which happens in some private windows.
+      </p>
+    </StaticProblem>
+  );
+}
+
+export function ReadFailed({ onRetry }: { readonly onRetry: () => void }) {
+  return (
+    <StaticProblem title="Couldn't read the recordings">
+      <p className="text-sm text-muted-foreground">
+        The browser didn't return the recordings saved here. Try again; if it keeps failing, close
+        other Know Meet tabs and reload the page.
+      </p>
+      <div>
+        <Button type="button" variant="secondary" onClick={onRetry}>
+          <KmIcon name="refresh" />
+          <span>Try again</span>
+        </Button>
+      </div>
+    </StaticProblem>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/library-view.tsx b/apps/web/src/presentation/local-recordings/presentation/library-view.tsx
