index 00000000..067d3b41
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/library-view.tsx
@@ -0,0 +1,173 @@
+// TJ-ARCH-MOB-001 compliant
+// The library (shape recordings-library.md §2, §4, §6, RL-1, RL-4): the signed-in
+// library's grammar without its cloud parts. Page head (eyebrow "On this device", h1
+// "Recordings"), the Browser storage strip, then the toolbar (labelled Sort select and
+// the Grid/List toggle group, whose pressed item carries a check) and the recordings as
+// cards or rows, newest first. A recording another tab is still writing comes first as
+// a card without a link. Storage unavailable replaces the strip and the list.
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { NativeSelect, NativeSelectOption } from "@know-meet/ui/components/native-select";
+import {
+  PageEyebrow,
+  PageHead,
+  PageHeadText,
+  PageSub,
+  PageTitle,
+} from "@know-meet/ui/components/page-head";
+import { ToggleGroup, ToggleGroupItem } from "@know-meet/ui/components/toggle-group";
+import { useId } from "react";
+import type { Recordings } from "../../../app/recordings/hooks";
+import {
+  type LibraryLayout,
+  type LibrarySort,
+  sortRecordings,
+} from "../application/recording-format";
+import { EmptyLibrary, LibrarySkeleton, ReadFailed, StorageUnavailable } from "./library-states";
+import { InProgressItem, type LibraryRow, RecordingCard, RecordingRow } from "./recording-items";
+import { StorageStrip } from "./storage-strip";
+
+const SORTS: readonly { readonly value: LibrarySort; readonly label: string }[] = [
+  { value: "new", label: "Newest first" },
+  { value: "old", label: "Oldest first" },
+  { value: "large", label: "Largest first" },
+];
+
+export interface LibraryControls {
+  readonly sort: LibrarySort;
+  readonly layout: LibraryLayout;
+}
+
+function Toolbar({
+  controls,
+  onChange,
+}: {
+  readonly controls: LibraryControls;
+  readonly onChange: (next: LibraryControls) => void;
+}) {
+  const sortId = useId();
+  const viewId = useId();
+  return (
+    <div className="mb-s4 flex flex-wrap items-end gap-x-s4 gap-y-s3 max-bp768:grid max-bp768:grid-cols-[minmax(0,1fr)]">
+      <div className="grid min-w-0 gap-1.5">
+        <label htmlFor={sortId} className="text-sm font-semibold">
+          Sort
+        </label>
+        <NativeSelect
+          id={sortId}
+          className="w-auto max-bp768:w-full"
+          value={controls.sort}
+          onChange={(event) => {
+            const sort = SORTS.find((option) => option.value === event.target.value);
+            if (sort !== undefined) onChange({ ...controls, sort: sort.value });
+          }}
+        >
+          {SORTS.map((option) => (
+            <NativeSelectOption key={option.value} value={option.value}>
+              {option.label}
+            </NativeSelectOption>
+          ))}
+        </NativeSelect>
+      </div>
+      <div className="grid min-w-0 gap-1.5">
+        <span id={viewId} className="text-sm font-semibold">
+          View
+        </span>
+        <ToggleGroup
+          aria-labelledby={viewId}
+          value={[controls.layout]}
+          onValueChange={(next) => {
+            const layout = next.includes("list") ? "list" : next.includes("grid") ? "grid" : null;
+            if (layout !== null) onChange({ ...controls, layout });
+          }}
+        >
+          <ToggleGroupItem value="grid">
+            <KmIcon name="film" className="size-4" />
+            <span>Grid</span>
+          </ToggleGroupItem>
+          <ToggleGroupItem value="list">
+            <KmIcon name="menu" className="size-4" />
+            <span>List</span>
+          </ToggleGroupItem>
+        </ToggleGroup>
+      </div>
+    </div>
+  );
+}
+
+function Items({
+  rows,
+  layout,
+}: {
+  readonly rows: readonly LibraryRow[];
+  readonly layout: LibraryLayout;
+}) {
+  const writing = rows.filter((row) => row.state === "recording");
+  const saved = rows.filter((row) => row.state !== "recording");
+  const items = [
+    ...writing.map((row) => <InProgressItem key={row.id} row={row} layout={layout} />),
+    ...saved.map((row) =>
+      layout === "list" ? (
+        <RecordingRow key={row.id} row={row} />
+      ) : (
+        <RecordingCard key={row.id} row={row} />
+      ),
+    ),
+  ];
+  return layout === "list" ? (
+    <ul className="grid gap-s2">{items}</ul>
+  ) : (
+    <ul className="grid grid-cols-[repeat(auto-fill,minmax(min(100%,300px),1fr))] gap-s4">
+      {items}
+    </ul>
+  );
+}
+
+interface LibraryViewProps {
+  readonly list: Recordings;
+  readonly canRecord: boolean;
+  readonly controls: LibraryControls;
+  readonly onControlsChange: (next: LibraryControls) => void;
+}
+
+function LibraryBody({ list, canRecord, controls, onControlsChange }: LibraryViewProps) {
+  if (list.loading) return <LibrarySkeleton />;
+  if (list.error !== null) return <ReadFailed onRetry={list.reload} />;
+  if (list.recordings.length === 0) return <EmptyLibrary canRecord={canRecord} />;
+  return (
+    <>
+      <Toolbar controls={controls} onChange={onControlsChange} />
+      <Items rows={sortRecordings(list.recordings, controls.sort)} layout={controls.layout} />
+    </>
+  );
+}
+
+export function LibraryView(props: LibraryViewProps) {
+  const unavailable = props.list.support === "unsupported";
+  return (
+    <>
+      <PageHead>
+        <PageHeadText>
+          <PageEyebrow>On this device</PageEyebrow>
+          <PageTitle>Recordings</PageTitle>
+          <PageSub>
+            Meetings recorded in this browser after everyone agreed. They stay on this device and
+            are never uploaded.
+          </PageSub>
+        </PageHeadText>
+      </PageHead>
+      {unavailable ? (
+        <StorageUnavailable />
+      ) : (
+        <>
+          <StorageStrip />
+          <section aria-labelledby="recordings-list-h">
+            <h2 id="recordings-list-h" className="sr-only">
+              Saved recordings
+            </h2>
+            <LibraryBody {...props} />
+          </section>
+        </>
+      )}
+    </>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/local-recordings-screen.tsx b/apps/web/src/presentation/local-recordings/presentation/local-recordings-screen.tsx
new file mode 100644
index 00000000..e1c86913
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/local-recordings-screen.tsx
@@ -0,0 +1,148 @@
+// TJ-ARCH-MOB-001 compliant
+// /recordings in the hosted build (wc10 task 10.5, shape
+// docs/design/shapes/web-conferencing/recordings-library.md; WC-8, WC-10, WC-13):
+// recordings made in this browser after everyone agreed, kept only on this device
+// (D1; nothing is uploaded). The library is the route itself; one recording opens at
+// `/recordings#recording:<id>` through client navigation only, so the id never reaches
+// a request (RL-12). The list is read again whenever the screen opens, so a recording
+// whose tab died shows as incomplete. The root carries the scenario contract id
+// `km-recordings-library` once the first read has finished, so whoever sees it sees
+// the real list, never the loading shell. The default build's /recordings stays the
+// prototype RecordingsScreen.
+//
+// Focus on a hash change: into the detail, its `h1`; back to the library (back link or
+// browser Back), the card that was opened; after a delete, the card that followed it,
+// or the `h1` when none did (shape §6).
+import type { RecordingRequestId } from "@know-meet/domain";
+import { Toaster, toast } from "@know-meet/ui/components/toast";
+import { useLocation, useNavigate } from "@tanstack/react-router";
+import { useEffect, useRef, useState } from "react";
+import { useRecordings, useRoomRecording } from "../../../app/recordings/hooks";
+import { ScreenPage } from "../../shared/screen-page";
+import { useDocumentTitle } from "../../shared/use-document-title";
+import { type LibraryLayout, sortRecordings } from "../application/recording-format";
+import { resolveRecordingsView } from "../application/recordings-route";
+import { type LibraryControls, LibraryView } from "./library-view";
+import { NotFoundView, OpeningView } from "./recording-detail-states";
+import { RecordingDetailView } from "./recording-detail-view";
+import type { LibraryRow } from "./recording-items";
+
+const LAYOUT_KEY = "km-recordings-layout";
+
+/** Grid/List is kept for the browser session only (shape §8); storage may be blocked. */
+function readLayout(): LibraryLayout {
+  try {
+    return window.sessionStorage.getItem(LAYOUT_KEY) === "list" ? "list" : "grid";
+  } catch {
+    return "grid";
+  }
+}
+
+function writeLayout(layout: LibraryLayout): void {
+  try {
+    window.sessionStorage.setItem(LAYOUT_KEY, layout);
+  } catch {
+    // Session storage blocked (some private windows): the choice lasts until reload.
+  }
+}
+
+function focusPageHeading(): void {
+  const heading = document.querySelector<HTMLElement>("main h1");
+  if (heading === null) return;
+  if (!heading.hasAttribute("tabindex")) heading.setAttribute("tabindex", "-1");
+  heading.focus({ preventScroll: true });
+}
+
+/** Focuses the link of a recording in the library; false when it is not shown. */
+function focusItem(id: RecordingRequestId): boolean {
+  const link = document.querySelector<HTMLElement>(
+    `[data-testid="km-recording-item"][data-recording-id="${CSS.escape(id)}"]`,
+  );
+  if (link === null) return false;
+  link.focus();
+  return true;
+}
+
+/** Reads the list once when the screen opens (the hook's `reload` may change identity). */
+function useReloadOnOpen(reload: () => void): void {
+  const latest = useRef(reload);
+  latest.current = reload;
+  useEffect(() => {
+    latest.current();
+  }, []);
+}
+
+export function LocalRecordingsScreen() {
+  useDocumentTitle("Recordings — Know Meet");
+  const hash = useLocation({ select: (location) => location.hash });
+  const navigate = useNavigate();
+  const view = resolveRecordingsView(hash);
+  const list = useRecordings();
+  const { support: recorderSupport } = useRoomRecording();
+  const [controls, setControls] = useState<LibraryControls>(() => ({
+    sort: "new",
+    layout: readLayout(),
+  }));
+  /** The card to focus when the library shows again: the one opened, or the one after a deleted one. */
+  const returnItem = useRef<RecordingRequestId | null>(null);
+  const previousHash = useRef(hash);
+  useReloadOnOpen(list.reload);
+
+  useEffect(() => {
+    if (previousHash.current === hash) return; // first render, or no change
+    previousHash.current = hash;
+    const current = resolveRecordingsView(hash);
+    if (current.kind === "detail") returnItem.current = current.id;
+    if (current.kind !== "list") {
+      window.scrollTo(0, 0);
+      focusPageHeading();
+      return;
+    }
+    const item = returnItem.current;
+    returnItem.current = null;
+    if (item === null || !focusItem(item)) {
+      window.scrollTo(0, 0);
+      focusPageHeading();
+    }
+  }, [hash]);
+
+  const onControlsChange = (next: LibraryControls) => {
+    if (next.layout !== controls.layout) writeLayout(next.layout);
+    setControls(next);
+  };
+
+  const onDeleted = (row: LibraryRow) => {
+    const saved = sortRecordings(
+      list.recordings.filter((entry) => entry.state !== "recording"),
+      controls.sort,
+    );
+    const index = saved.findIndex((entry) => entry.id === row.id);
+    returnItem.current = index === -1 ? null : (saved[index + 1]?.id ?? null);
+    toast.add({ title: "Recording deleted from this browser." });
+    void navigate({ to: "/recordings", replace: true });
+  };
+
+  const detailRow =
+    view.kind === "detail" ? (list.recordings.find((row) => row.id === view.id) ?? null) : null;
+
+  return (
+    <Toaster>
+      <ScreenPage data-testid={list.loading ? undefined : "km-recordings-library"}>
+        {view.kind === "list" ? (
+          <LibraryView
+            list={list}
+            canRecord={recorderSupport !== "unsupported"}
+            controls={controls}
+            onControlsChange={onControlsChange}
+          />
+        ) : detailRow !== null ? (
+          <RecordingDetailView key={detailRow.id} row={detailRow} onDeleted={onDeleted} />
+        ) : view.kind === "detail" && list.loading ? (
+          <OpeningView />
+        ) : (
+          <NotFoundView />
+        )}
+      </ScreenPage>
+    </Toaster>
+  );
+}
