+// TJ-ARCH-MOB-001 compliant
+// Detail states with no recording to show (shape recordings-library.md §6): opening
+// (the list's first read has not finished) and not found (the id does not parse, or no
+// recording with it is on this device, for example after it was deleted in another tab).
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+
+const backClass = cn(
+  "-ml-s2 inline-flex min-h-size-target w-fit items-center gap-s2 rounded-10 px-s2 text-sm font-semibold text-foreground no-underline",
+  focusFillClass,
+);
+
+function BackToLibrary() {
+  return (
+    <Link to="/recordings" className={backClass}>
+      <KmIcon name="chevron-right" className="size-4 rotate-180" />
+      <span>Recordings</span>
+    </Link>
+  );
+}
+
+export function OpeningView() {
+  return (
+    <section aria-busy="true" aria-labelledby="recording-opening-h" className="grid gap-s3">
+      <BackToLibrary />
+      <h1 id="recording-opening-h" tabIndex={-1} className="text-2xl outline-none">
+        Recording
+      </h1>
+      <p className="flex items-center gap-s2 text-sm text-muted-foreground">
+        <Spinner aria-hidden="true" role="presentation" className="motion-reduce:animate-none" />
+        <span>Opening the recording…</span>
+      </p>
+    </section>
+  );
+}
+
+export function NotFoundView() {
+  return (
+    <section aria-labelledby="recording-missing-h" className="grid gap-s3">
+      <BackToLibrary />
+      <h1 id="recording-missing-h" tabIndex={-1} className="text-2xl outline-none">
+        This recording isn't on this device
+      </h1>
+      <p className="max-w-measure-empty text-muted-foreground">
+        It may have been deleted, or the link came from another browser. Recordings stay in the
+        browser that made them.
+      </p>
+    </section>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/recording-detail-view.tsx b/apps/web/src/presentation/local-recordings/presentation/recording-detail-view.tsx
new file mode 100644
index 00000000..e556b23c
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/recording-detail-view.tsx
@@ -0,0 +1,213 @@
+// TJ-ARCH-MOB-001 compliant
+// One recording at `/recordings#recording:<id>` (shape recordings-library.md §2, §4,
+// §6-§8, RL-1, RL-6, RL-12): back link, h1 title and the facts line, the condition
+// note (stopped early, incomplete, file missing), the player, then Download (an anchor
+// on the object URL with the filename) and Delete (confirmed), and the link to the
+// meeting in History when one exists. The object URL is opened when the detail opens and
+// revoked when it closes (useRecordingPlayback). A missing file offers only Delete.
+import { parseMeetingHistoryId } from "@know-meet/domain";
+import { buttonVariants } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import type * as React from "react";
+import { useState } from "react";
+import {
+  type RecordingPlayback,
+  useDeleteRecording,
+  useRecordingPlayback,
+} from "../../../app/recordings/hooks";
+import { formatBytes } from "../../workspace/application/format";
+import {
+  clockTime,
+  detailFacts,
+  downloadFilename,
+  recordedMs,
+  recordingTitle,
+} from "../application/recording-format";
+import { DeleteRecordingDialog } from "./delete-recording-dialog";
+import type { LibraryRow } from "./recording-items";
+import { ConditionNote } from "./recording-parts";
+import { RecordingPlayer } from "./recording-player";
+
+const linkClass = cn(
+  "inline-flex min-h-size-target items-center gap-s2 rounded-10 px-s2 text-sm font-semibold text-foreground no-underline",
+  focusFillClass,
+);
+
+function BackLink() {
+  return (
+    <Link to="/recordings" className={cn(linkClass, "-ml-s2 mb-s2 w-fit")}>
+      <KmIcon name="chevron-right" className="size-4 rotate-180" />
+      <span>Recordings</span>
+    </Link>
+  );
+}
+
+function ConditionFor({ row }: { readonly row: LibraryRow }) {
+  if (row.state === "stopped-early") {
+    const at = row.endedAt === null ? "" : ` at ${clockTime(row.endedAt)}`;
+    return (
+      <ConditionNote tone="amber">
+        Browser storage ran out, so recording stopped{at}. Everything up to then was saved.
+      </ConditionNote>
+    );
+  }
+  if (row.state === "incomplete") {
+    return (
+      <ConditionNote tone="red">
+        This recording didn't finish saving. It may stop early or not play. Download it to try
+        another player, or delete it.
+      </ConditionNote>
+    );
+  }
+  return null;
+}
+
+/** The stage area for every playback state but `ready`. */
+function StageMessage({ children }: { readonly children: React.ReactNode }) {
+  return (
+    <div className="grid aspect-video place-items-center rounded-lg bg-media-bg p-s5">
+      <p className="flex max-w-[44ch] items-start gap-s2 text-sm text-foreground">{children}</p>
+    </div>
+  );
+}
+
+function PlaybackArea({
+  playback,
+  row,
+}: {
+  readonly playback: RecordingPlayback;
+  readonly row: LibraryRow;
+}) {
+  switch (playback.status) {
+    case "ready": {
+      const ms = recordedMs(row);
+      return (
+        <RecordingPlayer url={playback.url} recordedSeconds={ms === null ? null : ms / 1000} />
+      );
+    }
+    case "idle":
+    case "loading":
+      return (
+        <StageMessage>
+          <Spinner aria-hidden="true" role="presentation" className="motion-reduce:animate-none" />
+          <span>Opening the recording…</span>
+        </StageMessage>
+      );
+    case "recording":
+      return (
+        <StageMessage>
+          <KmIcon name="record" className="mt-px flex-none text-red-text" />
+          <span>
+            This recording is still being written in another tab. It can play once it ends.
+          </span>
+        </StageMessage>
+      );
+    case "missing":
+      return (
+        <StageMessage>
+          <KmIcon name="alert" className="mt-px flex-none text-red-text" />
+          <span>The browser removed this file, so it can't play. Delete the entry to tidy up.</span>
+        </StageMessage>
+      );
+    case "failed":
+      return (
+        <StageMessage>
+          <KmIcon name="alert" className="mt-px flex-none text-red-text" />
+          <span>This browser couldn't open the file. Reload the page to try again.</span>
+        </StageMessage>
+      );
+  }
+}
+
+function HistoryLink({ meetingId }: { readonly meetingId: string | null }) {
+  const id = parseMeetingHistoryId(meetingId);
+  if (id === null) return null;
+  return (
+    <Link to="/history" hash={`meeting:${id}`} className={cn(linkClass, "w-fit")}>
+      <KmIcon name="clock" className="size-4" />
+      <span>Meeting and chat in History</span>
+    </Link>
+  );
+}
+
+interface RecordingDetailViewProps {
+  readonly row: LibraryRow;
+  readonly onDeleted: (row: LibraryRow) => void;
+}
+
+export function RecordingDetailView({ row, onDeleted }: RecordingDetailViewProps) {
+  const playable = row.state !== "missing" && row.state !== "recording";
+  const playback = useRecordingPlayback(playable ? row.id : null);
+  const remover = useDeleteRecording();
+  const [confirmOpen, setConfirmOpen] = useState(false);
+  const [failed, setFailed] = useState(false);
+  const [deleted, setDeleted] = useState(false);
+  const title = recordingTitle(row);
+  const shown: RecordingPlayback = playable
+    ? playback
+    : { status: row.state === "missing" ? "missing" : "recording" };
+
+  const onConfirm = () => {
+    setFailed(false);
+    void remover.deleteRecording(row.id).then((removed) => {
+      if (!removed) {
+        setFailed(true);
+        return;
+      }
+      setDeleted(true);
+      setConfirmOpen(false);
+      onDeleted(row);
+    });
+  };
+
+  return (
+    <article aria-labelledby="recording-title" className="grid gap-s5">
+      <header className="grid gap-s1">
+        <BackLink />
+        <h1
+          id="recording-title"
+          tabIndex={-1}
+          className="text-2xl outline-none [overflow-wrap:anywhere]"
+        >
+          {title}
+        </h1>
+        <p className="text-sm text-muted-foreground">{detailFacts(row)}</p>
+      </header>
+      <ConditionFor row={row} />
+      <div className="grid w-full max-w-[960px] gap-s4 max-bp1024:max-w-[720px]">
+        <PlaybackArea playback={shown} row={row} />
+        <div className="flex flex-wrap gap-s3 max-bp768:grid max-bp768:grid-cols-[minmax(0,1fr)]">
+          {playback.status === "ready" ? (
+            <a
+              href={playback.url}
+              download={downloadFilename(row)}
+              className={cn(buttonVariants({ variant: "secondary" }), focusFillClass)}
+            >
+              <KmIcon name="download" />
+              <span>Download</span>
+            </a>
+          ) : null}
+          {row.state === "recording" ? null : (
+            <DeleteRecordingDialog
+              open={confirmOpen}
+              onOpenChange={(open) => {
+                if (!remover.pending) setConfirmOpen(open);
+                if (open) setFailed(false);
+              }}
+              size={formatBytes(row.sizeBytes)}
+              pending={remover.pending}
+              failed={failed}
+              returnFocus={!deleted}
+              onConfirm={onConfirm}
+            />
+          )}
+        </div>
+        <HistoryLink meetingId={row.meetingId} />
+      </div>
+    </article>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/recording-items.tsx b/apps/web/src/presentation/local-recordings/presentation/recording-items.tsx
new file mode 100644
index 00000000..b04d9577
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/recording-items.tsx
@@ -0,0 +1,160 @@
+// TJ-ARCH-MOB-001 compliant
+// Library entries (shape recordings-library.md §4-§6, RL-2, RL-7, RL-10): the card (the
+// whole card links to the detail; one action per card), the compact list row (same
+// content, plus Download as a trailing 44px icon link), and the not-focusable card of a
+// recording still being written in another tab. Linked cards drop their inner fills
+// while focused (DESIGN.md interactive card). Scenario contract: `km-recording-item` on
+// each link, with `data-duration-ms` (when known) and `data-size-bytes`.
+import { buttonVariants } from "@know-meet/ui/components/button";
+import { cardVariants } from "@know-meet/ui/components/card";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import { type Recordings, useRecordingPlayback } from "../../../app/recordings/hooks";
+import {
+  clockTime,
+  downloadFilename,
+  itemName,
+  metaLine,
+  recordedMs,
+  recordingTitle,
+} from "../application/recording-format";
+import { recordingDetailHash } from "../application/recordings-route";
+import { ChipRow, ConditionChip, FormatChip } from "./recording-parts";
+import { RecordingPoster } from "./recording-poster";
+
+export type LibraryRow = Recordings["recordings"][number];
+
+const linkFocusClass = cn(
+  focusFillClass,
+  "focus-visible:**:bg-transparent! focus-visible:**:text-inherit!",
+);
+
+/** The object URL of a playable file for its poster and download; null otherwise. */
+function usePosterUrl(row: LibraryRow): string | null {
+  const playable = row.state !== "recording" && row.state !== "missing";
+  const playback = useRecordingPlayback(playable ? row.id : null);
+  return playback.status === "ready" ? playback.url : null;
+}
+
+function Facts({ row }: { readonly row: LibraryRow }) {
+  return (
+    <>
+      <span className="text-sm text-muted-foreground [overflow-wrap:anywhere]">
+        {metaLine(row)}
+      </span>
+      <ChipRow>
+        <FormatChip mimeType={row.mimeType} />
+        <ConditionChip condition={row.state} />
+      </ChipRow>
+    </>
+  );
+}
+
+export function RecordingCard({ row }: { readonly row: LibraryRow }) {
+  const url = usePosterUrl(row);
+  return (
+    <li>
+      <Link
+        to="/recordings"
+        hash={recordingDetailHash(row.id)}
+        aria-label={itemName(row)}
+        data-testid="km-recording-item"
+        data-recording-id={row.id}
+        data-size-bytes={row.sizeBytes}
+        data-duration-ms={recordedMs(row) ?? undefined}
+        className={cn(cardVariants(), "gap-0 overflow-hidden p-0 max-bp768:p-0", linkFocusClass)}
+      >
+        <RecordingPoster url={url} />
+        <span className="grid min-w-0 gap-s2 p-s4">
+          <span className="truncate text-base font-semibold" title={recordingTitle(row)}>
+            {recordingTitle(row)}
+          </span>
+          <Facts row={row} />
+        </span>
+      </Link>
+    </li>
+  );
+}
+
+export function RecordingRow({ row }: { readonly row: LibraryRow }) {
+  const url = usePosterUrl(row);
+  const title = recordingTitle(row);
+  return (
+    <li className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-s2 rounded-base bg-surface pr-s3">
+      <Link
+        to="/recordings"
+        hash={recordingDetailHash(row.id)}
+        aria-label={itemName(row)}
+        data-testid="km-recording-item"
+        data-recording-id={row.id}
+        data-size-bytes={row.sizeBytes}
+        data-duration-ms={recordedMs(row) ?? undefined}
+        className={cn(
+          "grid grid-cols-[120px_minmax(0,1fr)] items-center gap-s3 rounded-base px-s4 py-s3 text-inherit no-underline transition-colors duration-(--dur-fast) [@media(hover:hover)]:hover:bg-card-hov max-bp768:grid-cols-[88px_minmax(0,1fr)]",
+          linkFocusClass,
+        )}
+      >
+        <RecordingPoster url={url} variant="thumb" />
+        <span className="grid min-w-0 gap-1">
+          <span className="truncate font-semibold" title={title}>
+            {title}
+          </span>
+          <Facts row={row} />
+        </span>
+      </Link>
+      {url === null ? null : (
+        <a
+          href={url}
+          download={downloadFilename(row)}
+          aria-label={`Download ${title}`}
+          className={cn(buttonVariants({ variant: "secondary", size: "icon" }), focusFillClass)}
+        >
+          <KmIcon name="download" />
+        </a>
+      )}
+    </li>
+  );
+}
+
+/** RL-7: a recording another tab is writing; no link, no actions, not focusable. */
+export function InProgressItem({
+  row,
+  layout,
+}: {
+  readonly row: LibraryRow;
+  readonly layout: "grid" | "list";
+}) {
+  const where = row.recordingHere ? "in this tab" : "in another tab";
+  const poster = (
+    <RecordingPoster url={null} variant={layout === "list" ? "thumb" : "card"}>
+      <span className="inline-flex items-center gap-1.5 rounded-pill bg-red-soft px-2.5 py-1 text-xs font-semibold text-foreground">
+        <span className="size-size-pip flex-none rounded-round bg-pip-red" />
+        Recording now
+      </span>
+    </RecordingPoster>
+  );
+  const text = (
+    <span className="grid min-w-0 gap-1">
+      <span className="truncate font-semibold">{recordingTitle(row)}</span>
+      <span className="text-sm text-muted-foreground">
+        Started {clockTime(row.startedAt)} {where}
+      </span>
+      <span className="sr-only">Recording now {where}</span>
+    </span>
+  );
+  return (
+    <li
+      className={cn(
+        "rounded-tile bg-surface",
+        layout === "list"
+          ? "grid grid-cols-[120px_minmax(0,1fr)] items-center gap-s3 px-s4 py-s3 max-bp768:grid-cols-[88px_minmax(0,1fr)]"
+          : "grid overflow-hidden",
+      )}
+    >
+      {poster}
+      {layout === "list" ? text : <span className="grid p-s4">{text}</span>}
+    </li>
+  );
+}
