--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/recording-poster.tsx
@@ -0,0 +1,59 @@
+// TJ-ARCH-MOB-001 compliant
+// The card poster (shape recordings-library.md §2 assumption, §4): a frame of the
+// recording itself, from a muted `<video preload="metadata">` seeked to 1 s (or to the
+// middle of a shorter file). It never plays and is hidden from assistive technology;
+// the card's name carries the content. Until a frame shows, or when the file has no
+// readable frame, the poster is the `tile` fill with the `film` glyph. The URL is a
+// `blob:` object URL of the local file (RL-12); nothing is fetched.
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { cn } from "@know-meet/ui/lib/utils";
+import type * as React from "react";
+import { useState } from "react";
+
+const FRAME_SECONDS = 1;
+
+function seekToFrame(event: React.SyntheticEvent<HTMLVideoElement>): void {
+  const video = event.currentTarget;
+  const duration = Number.isFinite(video.duration) ? video.duration : FRAME_SECONDS * 2;
+  video.currentTime = Math.min(FRAME_SECONDS, duration / 2);
+}
+
+interface RecordingPosterProps {
+  /** Object URL of the file; null while it opens or when it cannot be opened. */
+  readonly url: string | null;
+  readonly variant?: "card" | "thumb";
+  /** Shown instead of the frame (a recording still being written). */
+  readonly children?: React.ReactNode;
+}
+
+export function RecordingPoster({ url, variant = "card", children }: RecordingPosterProps) {
+  const [frame, setFrame] = useState<"waiting" | "shown" | "failed">("waiting");
+  const showVideo = url !== null && frame !== "failed" && children === undefined;
+  return (
+    <div
+      aria-hidden="true"
+      className={cn(
+        "relative grid aspect-video place-items-center overflow-hidden bg-tile text-muted-foreground",
+        variant === "thumb" ? "rounded-8" : "",
+      )}
+    >
+      {children ?? (frame === "shown" ? null : <KmIcon name="film" className="size-7" />)}
+      {showVideo ? (
+        <video
+          src={url}
+          preload="metadata"
+          muted
+          playsInline
+          tabIndex={-1}
+          onLoadedMetadata={seekToFrame}
+          onSeeked={() => setFrame("shown")}
+          onError={() => setFrame("failed")}
+          className={cn(
+            "absolute inset-0 size-full object-cover",
+            frame === "shown" ? "" : "opacity-0",
+          )}
+        />
+      ) : null}
+    </div>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/storage-strip.tsx b/apps/web/src/presentation/local-recordings/presentation/storage-strip.tsx
new file mode 100644
index 00000000..6c4109ca
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/storage-strip.tsx
@@ -0,0 +1,145 @@
+// TJ-ARCH-MOB-001 compliant
+// The "Browser storage" strip (shape recordings-library.md §5-§7, RL-3): a `panel` card
+// with the space this site uses and may use (`storage.estimate()`, approximate, hence
+// "About"), a meter (`muted` track; fill `meter-fill` under 80%, `amber` to 95%, `red`
+// above, and the text changes with the band, so colour is never alone) and whether the
+// browser may clear recordings. "Keep recordings" asks `navigator.storage.persist()`
+// from the click; the button goes once the browser answered, and the line says what it
+// answered (a polite live line; focus moves to it, since the button that held focus is
+// gone). Stacks below 768 (text, meter, button).
+import { Button } from "@know-meet/ui/components/button";
+import { cardVariants } from "@know-meet/ui/components/card";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import { cn } from "@know-meet/ui/lib/utils";
+import { useId, useRef, useState } from "react";
+import { useRecordingStorage } from "../../../app/recordings/hooks";
+import { formatBytes } from "../../workspace/application/format";
+import { type StorageBand, storageUse } from "../application/recording-format";
+
+const BAND_FILL: Readonly<Record<StorageBand, string>> = {
+  ok: "bg-meter-fill",
+  high: "bg-amber",
+  full: "bg-red",
+};
+
+const BAND_WORDS: Readonly<Record<StorageBand, string>> = {
+  ok: "",
+  high: "Getting full.",
+  full: "Almost full.",
+};
+
+function Meter({
+  usedBytes,
+  quotaBytes,
+}: {
+  readonly usedBytes: number;
+  readonly quotaBytes: number;
+}) {
+  const use = storageUse(usedBytes, quotaBytes);
+  const words = BAND_WORDS[use.band];
+  return (
+    <>
+      <div
+        role="img"
+        aria-label={`${formatBytes(usedBytes)} used of about ${formatBytes(quotaBytes)} available.${words === "" ? "" : ` ${words}`}`}
+        className="h-2.5 overflow-hidden rounded-pill bg-muted"
+      >
+        <span
+          aria-hidden="true"
+          className={cn("block h-full rounded-[inherit]", BAND_FILL[use.band])}
+          style={{ width: `${use.percent}%` }}
+        />
+      </div>
+      <p className="text-sm text-muted-foreground">
+        <span className="whitespace-nowrap">{formatBytes(usedBytes)}</span> used by Know Meet in
+        this browser. About <span className="whitespace-nowrap">{formatBytes(quotaBytes)}</span>{" "}
+        available to this site.
+        {words === "" ? null : <strong className="font-semibold text-foreground"> {words}</strong>}
+      </p>
+    </>
+  );
+}
+
+type PersistAnswer = "none" | "asked";
+
+export function StorageStrip() {
+  const headingId = useId();
+  const { info, requestPersistence, requesting } = useRecordingStorage();
+  const [answer, setAnswer] = useState<PersistAnswer>("none");
+  const lineRef = useRef<HTMLParagraphElement>(null);
+  const persisted = info?.persisted ?? false;
+
+  const onKeep = () => {
+    void requestPersistence().then(() => {
+      setAnswer("asked");
+      requestAnimationFrame(() => lineRef.current?.focus({ preventScroll: true }));
+    });
+  };
+
+  const persistLine = persisted
+    ? "Protected from automatic clearing."
+    : answer === "asked"
+      ? "The browser didn't allow this. Download recordings you want to keep."
+      : "The browser may clear recordings if the device runs low on space.";
+
+  return (
+    <section
+      aria-labelledby={headingId}
+      aria-busy={info === null ? true : undefined}
+      className={cn(
+        cardVariants({ variant: "panel" }),
+        "mb-s6 grid-cols-[minmax(0,1fr)_auto] items-center max-bp768:grid-cols-[minmax(0,1fr)]",
+      )}
+    >
+      <div className="grid min-w-0 gap-s2">
+        <h2 id={headingId} className="text-base">
+          Browser storage
+        </h2>
+        {info === null ? (
+          <p className="text-sm text-muted-foreground">Checking how much space this browser has…</p>
+        ) : info.usedBytes !== null && info.quotaBytes !== null ? (
+          <Meter usedBytes={info.usedBytes} quotaBytes={info.quotaBytes} />
+        ) : (
+          <p className="text-sm text-muted-foreground">
+            This browser doesn't say how much space is free.
+          </p>
+        )}
+        {info === null ? null : (
+          <p
+            ref={lineRef}
+            tabIndex={-1}
+            aria-live="polite"
+            className="flex items-start gap-s2 text-sm outline-none"
+          >
+            <KmIcon
+              name={persisted ? "shield" : "info"}
+              className="mt-px size-4 text-muted-foreground"
+            />
+            <span>{persistLine}</span>
+          </p>
+        )}
+      </div>
+      {info === null || persisted || answer === "asked" ? null : (
+        <Button
+          type="button"
+          variant="secondary"
+          disabled={requesting}
+          focusableWhenDisabled
+          onClick={onKeep}
+        >
+          {requesting ? (
+            <Spinner
+              aria-hidden="true"
+              role="presentation"
+              className="motion-reduce:animate-none"
+            />
+          ) : (
+            <KmIcon name="shield" />
+          )}
+          <span>Keep recordings</span>
+        </Button>
+      )}
+    </section>
+  );
+}
diff --git a/apps/web/src/presentation/local-recordings/presentation/use-video-player.ts b/apps/web/src/presentation/local-recordings/presentation/use-video-player.ts
new file mode 100644
index 00000000..2b027e15
--- /dev/null
+++ b/apps/web/src/presentation/local-recordings/presentation/use-video-player.ts
@@ -0,0 +1,138 @@
+// TJ-ARCH-MOB-001 compliant
+// State and actions of the detail player over a real `<video>` (shape
+// recordings-library.md §8, RL-5): play/pause, time, seek, mute, speed and full screen,
+// mirrored from the element's own events so the controls never disagree with it.
+// Chromium's MediaRecorder WebM often reports an unknown (Infinity) duration and may not
+// seek; the recorded length from the library row is used for the scale instead, and a
+// seek the browser refuses simply leaves the time where it is. The element's own error
+// event is the "playback error" state. Nothing here autoplays.
+import type * as React from "react";
+import { useCallback, useEffect, useRef, useState } from "react";
+
+export interface VideoPlayer {
+  readonly videoRef: React.RefObject<HTMLVideoElement | null>;
+  readonly regionRef: React.RefObject<HTMLElement | null>;
+  readonly playing: boolean;
+  /** Seconds played. */
+  readonly time: number;
+  /** Seconds in the file, or the recorded length when the file does not say; null if neither. */
+  readonly duration: number | null;
+  readonly muted: boolean;
+  readonly speed: number;
+  readonly fullscreen: boolean;
+  readonly fullscreenAvailable: boolean;
+  readonly failed: boolean;
+  readonly toggle: () => void;
+  readonly seek: (seconds: number) => void;
+  readonly seekBy: (deltaSeconds: number) => void;
+  readonly toggleMuted: () => void;
+  readonly setSpeed: (speed: number) => void;
+  readonly toggleFullscreen: () => void;
+  /** Spread on the `<video>`. */
+  readonly videoEvents: React.ComponentProps<"video">;
+}
+
+function finiteOrNull(value: number): number | null {
+  return Number.isFinite(value) && value > 0 ? value : null;
+}
+
+export function useVideoPlayer(recordedSeconds: number | null): VideoPlayer {
+  const videoRef = useRef<HTMLVideoElement>(null);
+  const regionRef = useRef<HTMLElement>(null);
+  const [playing, setPlaying] = useState(false);
+  const [time, setTime] = useState(0);
+  const [fileDuration, setFileDuration] = useState<number | null>(null);
+  const [muted, setMuted] = useState(false);
+  const [speed, setSpeedState] = useState(1);
+  const [fullscreen, setFullscreen] = useState(false);
+  const [failed, setFailed] = useState(false);
+  const fullscreenAvailable = typeof document !== "undefined" && document.fullscreenEnabled;
+
+  useEffect(() => {
+    const onChange = () => setFullscreen(document.fullscreenElement === regionRef.current);
+    document.addEventListener("fullscreenchange", onChange);
+    return () => document.removeEventListener("fullscreenchange", onChange);
+  }, []);
+
+  const duration = fileDuration ?? recordedSeconds;
+
+  const toggle = useCallback(() => {
+    const video = videoRef.current;
+    if (video === null) return;
+    if (video.paused || video.ended) {
+      void video.play().catch(() => setPlaying(false));
+    } else {
+      video.pause();
+    }
+  }, []);
+
+  const seek = useCallback(
+    (seconds: number) => {
+      const video = videoRef.current;
+      if (video === null) return;
+      const end = duration ?? Number.POSITIVE_INFINITY;
+      const next = Math.max(0, Math.min(end, seconds));
+      video.currentTime = next;
+      setTime(video.currentTime);
+    },
+    [duration],
+  );
+
+  const seekBy = useCallback(
+    (delta: number) => seek((videoRef.current?.currentTime ?? 0) + delta),
+    [seek],
+  );
+
+  const toggleMuted = useCallback(() => {
+    const video = videoRef.current;
+    if (video !== null) video.muted = !video.muted;
+  }, []);
+
+  const setSpeed = useCallback((next: number) => {
+    const video = videoRef.current;
+    if (video !== null) video.playbackRate = next;
+  }, []);
+
+  const toggleFullscreen = useCallback(() => {
+    const region = regionRef.current;
+    if (region === null || !document.fullscreenEnabled) return;
+    if (document.fullscreenElement === region)
+      void document.exitFullscreen().catch(() => undefined);
+    else void region.requestFullscreen().catch(() => undefined);
+  }, []);
+
+  const videoEvents: React.ComponentProps<"video"> = {
+    onPlay: () => setPlaying(true),
+    onPause: () => setPlaying(false),
+    onEnded: () => setPlaying(false),
+    onTimeUpdate: (event) => setTime(event.currentTarget.currentTime),
+    onLoadedMetadata: (event) => setFileDuration(finiteOrNull(event.currentTarget.duration)),
+    onDurationChange: (event) => setFileDuration(finiteOrNull(event.currentTarget.duration)),
+    onVolumeChange: (event) => setMuted(event.currentTarget.muted),
+    onRateChange: (event) => setSpeedState(event.currentTarget.playbackRate),
+    onError: () => {
+      setFailed(true);
+      setPlaying(false);
+    },
+  };
+
+  return {
+    videoRef,
+    regionRef,
+    playing,
+    time,
+    duration,
+    muted,
+    speed,
+    fullscreen,
+    fullscreenAvailable,
+    failed,
+    toggle,
+    seek,
+    seekBy,
+    toggleMuted,
+    setSpeed,
+    toggleFullscreen,
+    videoEvents,
+  };
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/consent-prompt.tsx b/apps/web/src/presentation/meeting-room/presentation/recording/consent-prompt.tsx
