@@ -0,0 +1,73 @@
+// TJ-ARCH-MOB-001 compliant
+// The recording consent question (wc10 task 10.4; WC-8, WC-9; decisions D1, D2), the
+// prototype `#consent-dlg` grammar on the kit AlertDialog. Shown to every other present
+// participant when someone asks to record (`phase: asking`), and to a late joiner while
+// a recording already runs (`running`): there a decline stops it for everyone and keeps
+// what was written. It is a question that needs an answer, so it stays open until one
+// of its two buttons answers it (Escape and the scrim do nothing). Neither answer is a
+// default: focus starts on the decline button, the choice that changes nothing on
+// anyone's device. Scenario contract: `km-recording-consent-prompt`, `-agree`,
+// `-decline`.
+import type { ConsentAnswer, ConsentPrompt as Prompt } from "@know-meet/domain";
+import {
+  AlertDialog,
+  AlertDialogAction,
+  AlertDialogContent,
+  AlertDialogDescription,
+  AlertDialogFooter,
+  AlertDialogHeader,
+  AlertDialogMedia,
+  AlertDialogTitle,
+} from "@know-meet/ui/components/alert-dialog";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { useId } from "react";
+import { type NameOf, promptText, RECORD_COPY, runningText } from "./recording-copy";
+
+interface ConsentPromptProps {
+  readonly prompt: Prompt | null;
+  readonly nameOf: NameOf;
+  readonly onAnswer: (answer: ConsentAnswer) => void;
+}
+
+export function ConsentPrompt({ prompt, nameOf, onAnswer }: ConsentPromptProps) {
+  const declineId = useId();
+  const running = prompt?.running ?? false;
+  const requester = prompt === null ? "" : nameOf(prompt.requester);
+  return (
+    <AlertDialog open={prompt !== null} onOpenChange={() => undefined}>
+      <AlertDialogContent
+        data-testid="km-recording-consent-prompt"
+        initialFocus={() => document.getElementById(declineId)}
+      >
+        <AlertDialogHeader>
+          <AlertDialogMedia className="bg-red-soft text-red-text">
+            <KmIcon name="record" />
+          </AlertDialogMedia>
+          <AlertDialogTitle>
+            {running ? RECORD_COPY.runningTitle : RECORD_COPY.promptTitle}
+          </AlertDialogTitle>
+          <AlertDialogDescription>
+            {running ? runningText(requester) : promptText(requester)}
+          </AlertDialogDescription>
+        </AlertDialogHeader>
+        <AlertDialogFooter>
+          <AlertDialogAction
+            id={declineId}
+            variant="secondary"
+            data-testid="km-recording-consent-decline"
+            onClick={() => onAnswer("declined")}
+          >
+            {running ? RECORD_COPY.runningDecline : RECORD_COPY.promptDecline}
+          </AlertDialogAction>
+          <AlertDialogAction
+            data-testid="km-recording-consent-agree"
+            onClick={() => onAnswer("agreed")}
+          >
+            <KmIcon name="check" />
+            <span>{running ? RECORD_COPY.runningAgree : RECORD_COPY.promptAgree}</span>
+          </AlertDialogAction>
+        </AlertDialogFooter>
+      </AlertDialogContent>
+    </AlertDialog>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/record-control.tsx b/apps/web/src/presentation/meeting-room/presentation/recording/record-control.tsx
new file mode 100644
index 00000000..7679d5d0
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/recording/record-control.tsx
@@ -0,0 +1,56 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html `#ctl-rec` for the local recording (wc10 task 10.4, WC-8, WC-9): in the
+// media group after Share, as in the prototype. "Record" asks everyone to agree; while
+// the request waits it reads "Cancel" and withdraws it; while this browser records it
+// reads "Stop rec", takes the active tone and stops on one press (what was written is
+// kept, so no confirmation; scenario contract `km-room-record`, `data-state` "on" only
+// while this browser records). When another recording or question is open, or the
+// browser cannot record, the control keeps its tab stop but is unavailable
+// (aria-disabled, reason linked by aria-describedby); a press announces the reason.
+import { useId } from "react";
+import { Ctl } from "../room-control";
+import { RECORD_COPY } from "./recording-copy";
+import type { RecordAction } from "./use-recording-ui";
+
+interface RecordControlProps {
+  readonly action: RecordAction;
+  readonly onPress: () => void;
+}
+
+export function RecordControl({ action, onPress }: RecordControlProps) {
+  const reasonId = useId();
+  const recording = action.kind === "stop";
+  const label =
+    action.kind === "stop"
+      ? RECORD_COPY.controlStop
+      : action.kind === "withdraw"
+        ? RECORD_COPY.controlCancel
+        : RECORD_COPY.controlRecord;
+  const name =
+    action.kind === "stop"
+      ? RECORD_COPY.controlStopName
+      : action.kind === "withdraw"
+        ? RECORD_COPY.controlCancelName
+        : RECORD_COPY.controlRecordName;
+  const blocked = action.kind === "blocked";
+  return (
+    <>
+      <Ctl
+        icon={recording ? "stop" : "record"}
+        label={label}
+        aria-label={name}
+        tone={recording ? "active" : "rest"}
+        data-testid="km-room-record"
+        data-state={recording ? "on" : "off"}
+        aria-disabled={blocked ? true : undefined}
+        aria-describedby={blocked ? reasonId : undefined}
+        onClick={onPress}
+      />
+      {blocked ? (
+        <span id={reasonId} className="sr-only">
+          {action.reason}
+        </span>
+      ) : null}
+    </>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/recording-copy.ts b/apps/web/src/presentation/meeting-room/presentation/recording/recording-copy.ts
new file mode 100644
index 00000000..9886ce12
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/recording/recording-copy.ts
@@ -0,0 +1,129 @@
+// TJ-ARCH-MOB-001 compliant
+// On-screen copy for recording in the room (wc10 task 10.4; WC-8, WC-9, decisions D1,
+// D2). Plain and calm (shapes README rule 7): the audience and the place are explicit
+// ("only in their browser", "never uploaded"), errors give the cause, then the fix.
+// Names come from the room snapshot; an identity no longer in the room reads "Someone".
+import type { RecordRequestError } from "@know-meet/application";
+import type {
+  ConsentNotice,
+  DeclineReason,
+  ParticipantIdentity,
+  RecordingEndReason,
+} from "@know-meet/domain";
+
+export const RECORD_COPY = {
+  controlRecord: "Record",
+  controlRecordName: "Record this meeting",
+  controlCancel: "Cancel",
+  controlCancelName: "Cancel recording request",
+  controlStop: "Stop rec",
+  controlStopName: "Stop recording",
+  unsupported:
+    "This browser can't record meetings. Recording works in current Chrome, Edge, Firefox and Safari on a computer.",
+  busyPrompted: "Answer the open recording question first.",
+  indicator: "Recording",
+  indicatorName: "This meeting is being recorded",
+  askingTitle: "Asking everyone to agree",
+  askingText:
+    "Recording starts only when everyone says yes. It's saved only in this browser, never uploaded.",
+  cancelRequest: "Cancel request",
+  dismiss: "Dismiss",
+  promptTitle: "Record this meeting?",
+  promptAgree: "Agree to recording",
+  promptDecline: "Don't record",
+  runningTitle: "This meeting is being recorded",
+  runningAgree: "Agree and stay",
+  runningDecline: "Decline and stop it",
+  startedHere: "You're recording this meeting. It's saved only in this browser.",
+  startedElsewhere: "Recording started. Everyone in the meeting sees the recording notice.",
+  stopped: "Recording stopped.",
+  asked: "Asking everyone to agree to a recording.",
+  withdrawn: "Recording request cancelled.",
+} as const;
+
+const SOMEONE = "Someone";
+
+export type NameOf = (identity: ParticipantIdentity) => string;
+
+/** Display names by identity, from the participants the room knows now. */
+export function namesFrom(
+  people: readonly { readonly identity: ParticipantIdentity; readonly displayName: string }[],
+): NameOf {
+  const names = new Map(people.map((person) => [person.identity, person.displayName] as const));
+  return (identity) => {
+    const name = names.get(identity)?.trim();
+    return name === undefined || name === "" ? SOMEONE : name;
+  };
+}
+
+/** "Guest B", "Guest B and Guest C", "Guest B and 2 others". */
+export function listNames(identities: readonly ParticipantIdentity[], nameOf: NameOf): string {
+  const [first, second, ...rest] = identities;
+  if (first === undefined) return "";
+  if (second === undefined) return nameOf(first);
+  if (rest.length === 0) return `${nameOf(first)} and ${nameOf(second)}`;
+  return `${nameOf(first)} and ${rest.length + 1} others`;
+}
+
+export function promptText(requester: string): string {
+  return `${requester} wants to record this meeting in their own browser. The file stays on their device and is never uploaded. Recording starts only if everyone agrees.`;
+}
+
+export function runningText(recorder: string): string {
+  return `${recorder} is recording this meeting in their own browser. If you decline, the recording stops for everyone; what was recorded before you joined is kept.`;
+}
+
+export function waitingText(awaiting: string): string {
+  return awaiting === "" ? "Starting…" : `Waiting for ${awaiting}.`;
+}
+
+export function lateJoinerText(pending: string): string {
+  return `${pending} just joined and is being asked. If they decline, the recording stops and what was recorded is kept.`;
+}
+
+export function remoteBusyText(recorder: string): string {
+  return `${recorder} is already recording. One recording at a time.`;
+}
+
+const DECLINED_BY: Readonly<Record<DeclineReason, (name: string) => string>> = {
+  person: (name) => `${name} declined, so nothing was recorded.`,
+  busy: (name) =>
+    `${name} couldn't answer because another recording question is open for them. Nothing was recorded.`,
+};
+
+const STOPPED_BECAUSE: Readonly<Record<RecordingEndReason, string>> = {
+  "recorder-stopped": "The recording stopped.",
+  "participant-declined":
+    "Someone who joined declined, so the recording stopped. What was recorded before is kept.",
+  "recorder-failed":
+    "The recording stopped because of a recording error. What was recorded before is kept.",
+  "consent-error":
+    "The recording stopped because consent couldn't be confirmed. What was recorded before is kept.",
+  "recorder-left": "The person recording left, so the recording stopped.",
+  disconnected:
+    "The connection dropped, so the recording stopped. What was recorded before is kept.",
+};
+
+export function noticeText(notice: ConsentNotice, nameOf: NameOf): string {
+  switch (notice.kind) {
+    case "declined":
+      return DECLINED_BY[notice.reason](nameOf(notice.by));
+    case "request-not-sent":
+      return "Your request didn't reach everyone, so nothing was recorded. Check your connection and try again.";
+    case "recorder-failed":
+      return "This browser couldn't start recording, so nothing was recorded. Try again, or try current Chrome on a computer.";
+    case "recording-stopped":
+      return STOPPED_BECAUSE[notice.reason];
+  }
+}
+
+export function requestErrorText(error: RecordRequestError): string {
+  switch (error.code) {
+    case "recording-busy":
+      return "A recording question is already open in this meeting. Wait for it to finish, then try again.";
+    case "recorder-failed":
+      return RECORD_COPY.unsupported;
+    case "connection-lost":
+      return "You're not connected. Wait for the connection to come back, then try again.";
+  }
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/recording-indicator.tsx b/apps/web/src/presentation/meeting-room/presentation/recording/recording-indicator.tsx
new file mode 100644
index 00000000..ff0ca724
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/recording/recording-indicator.tsx
@@ -0,0 +1,41 @@
+// TJ-ARCH-MOB-001 compliant
+// meet.html `.rec-ind` (wc10 task 10.4, WC-8, WC-9): the recording notice in the room
+// head, shown to every participant while a recording runs or starts anywhere in the
+// room (`indicatorOn`) and to nobody otherwise (scenario contract
+// `km-recording-indicator`). A `red-soft` pill with the `pip-red` pip, the word
+// "Recording" (state is never colour alone) and the time since this page saw it start.
+// The pip does not blink: no motion to opt out of. Its appearance is announced once by
+// the room's status region, so the pill itself is not a live region.
+import { useEffect, useState } from "react";
+import { formatDuration } from "../../../workspace/application/format";
+import { RECORD_COPY } from "./recording-copy";
+
+const TICK_MS = 1000;
+
+function useElapsed(): number {
+  const [startedAt] = useState(() => Date.now());
+  const [now, setNow] = useState(startedAt);
+  useEffect(() => {
+    const timer = window.setInterval(() => setNow(Date.now()), TICK_MS);
+    return () => window.clearInterval(timer);
+  }, []);
+  return now - startedAt;
+}
+
+export function RecordingIndicator({ recorder }: { readonly recorder: string }) {
+  const elapsed = useElapsed();
+  return (
+    <span
+      data-testid="km-recording-indicator"
+      title={`${RECORD_COPY.indicatorName} by ${recorder}`}
+      className="inline-flex min-h-8 flex-none items-center gap-1.5 rounded-pill bg-red-soft px-2.5 text-xs font-semibold whitespace-nowrap text-foreground"
+    >
+      <span aria-hidden="true" className="size-size-pip flex-none rounded-round bg-pip-red" />
+      <span>{RECORD_COPY.indicator}</span>
+      <span className="sr-only">, by {recorder}</span>
+      <span aria-hidden="true" className="font-mono tabular-nums max-bp481:hidden">
+        {formatDuration(elapsed)}
+      </span>
+    </span>
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/recording-notice.tsx b/apps/web/src/presentation/meeting-room/presentation/recording/recording-notice.tsx
new file mode 100644
index 00000000..a5bd6953
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/recording/recording-notice.tsx
@@ -0,0 +1,108 @@
+// TJ-ARCH-MOB-001 compliant
+// Recording notes in the room's notices row (wc10 task 10.4; WC-8, WC-9; D2), in the
+// Enable audio prompt's grammar: a note on a fill (Flat 2.0), glyph, one line of cause,
+// one action. Three cases, at most one at a time:
+// - the requester waits for answers: who is still asked, and "Cancel request";
+// - this browser records and a late joiner is being asked: what a decline would do;
+// - a one-time notice (declined, not sent, recorder failed, stopped): static text in a
+//   role="status" note with "Dismiss". A decline carries the scenario contract id
+//   `km-recording-request-declined`. As with the room head's connection chip, the note
+//   is `aria-live="off"`: the room's one status region announces it (useRecordingUi).
+// Notes sit on `surface` because they hold a button (controls only on bg, bg-2,
+// surface or card); the glyph carries the tone.
+import { Button } from "@know-meet/ui/components/button";
+import { KmIcon, type KmIconName } from "@know-meet/ui/components/km-icon";
+import { cn } from "@know-meet/ui/lib/utils";
+import type * as React from "react";
+import type { RoomRecordingView } from "../../../../app/recordings/hooks";
+import {
+  lateJoinerText,
+  listNames,
+  type NameOf,
+  noticeText,
+  RECORD_COPY,
+  waitingText,
+} from "./recording-copy";
+
+const noteClass =
+  "mx-auto flex w-[min(100%,760px)] flex-wrap items-center gap-x-s3 gap-y-s2 rounded-base px-s4 py-s3 text-foreground";
+
+interface NoteProps extends Omit<React.ComponentProps<"div">, "children"> {
+  readonly icon: KmIconName;
+  readonly tone: "record" | "warn";
+  readonly text: React.ReactNode;
+  readonly action: React.ReactNode;
+}
+
+function Note({ icon, tone, text, action, className, ...props }: NoteProps) {
+  return (
+    <div className={cn(noteClass, "bg-surface", className)} {...props}>
+      <KmIcon
+        name={icon}
+        className={cn("size-5 flex-none", tone === "warn" ? "text-amber-text" : "text-red-text")}
+      />
+      <div className="min-w-0 flex-1 text-sm">{text}</div>
+      {action}
+    </div>
+  );
+}
+
+interface RecordingNoticeProps {
+  readonly recording: RoomRecordingView;
+  readonly nameOf: NameOf;
+}
+
+export function RecordingNotice({ recording, nameOf }: RecordingNoticeProps) {
+  const { state, notice } = recording;
+
+  if (state.status === "requesting") {
+    return (
+      <Note
+        icon="record"
+        tone="record"
+        text={
+          <>
+            <p className="font-semibold">{RECORD_COPY.askingTitle}</p>
+            <p className="text-muted-foreground">
+              {waitingText(listNames(state.awaiting, nameOf))} {RECORD_COPY.askingText}
+            </p>
+          </>
+        }
+        action={
+          <Button type="button" variant="secondary" onClick={recording.withdraw}>
+            {RECORD_COPY.cancelRequest}
+          </Button>
+        }
+      />
+    );
+  }
+
+  if (state.status === "local-recording" && state.pending.length > 0) {
+    return (
+      <Note
+        icon="users"
+        tone="record"
+        text={<p>{lateJoinerText(listNames(state.pending, nameOf))}</p>}
+        action={null}
+      />
+    );
+  }
+
+  if (notice === null) return null;
+  const declined = notice.kind === "declined";
+  return (
+    <Note
+      role="status"
+      aria-live="off"
+      icon={declined ? "x" : "alert"}
+      tone="warn"
+      data-testid={declined ? "km-recording-request-declined" : undefined}
+      text={<p>{noticeText(notice, nameOf)}</p>}
+      action={
+        <Button type="button" variant="secondary" onClick={recording.dismissNotice}>
+          {RECORD_COPY.dismiss}
+        </Button>
+      }
+    />
+  );
+}
diff --git a/apps/web/src/presentation/meeting-room/presentation/recording/use-recording-ui.ts b/apps/web/src/presentation/meeting-room/presentation/recording/use-recording-ui.ts
new file mode 100644
index 00000000..49fd4478
--- /dev/null
+++ b/apps/web/src/presentation/meeting-room/presentation/recording/use-recording-ui.ts
@@ -0,0 +1,107 @@
+// TJ-ARCH-MOB-001 compliant
+// The room's recording view model (wc10 task 10.4): the consent state from
+// `useRoomRecording`, participant names for the copy, and the one action the Record
+// control performs in each state (request, cancel the request, stop). A refused request
+// is announced with its cause and fix. The indicator turning on or off and each new
+// one-time notice are announced once through the room's status region; the prompt
+// speaks for itself (alertdialog).
+import type { RoomSnapshot } from "@know-meet/application";
+import { useEffect, useMemo, useRef } from "react";
+import { type RoomRecordingView, useRoomRecording } from "../../../../app/recordings/hooks";
+import type { Announce } from "../../../guest-meeting/live-status";
+import {
+  type NameOf,
+  namesFrom,
+  noticeText,
+  RECORD_COPY,
+  requestErrorText,
+} from "./recording-copy";
+
+/** What pressing Record does now; `blocked` explains instead of acting. */
+export type RecordAction =
+  | { readonly kind: "request" }
+  | { readonly kind: "withdraw" }
+  | { readonly kind: "stop" }
+  | { readonly kind: "blocked"; readonly reason: string };
+
+export interface RecordingUi {
+  readonly recording: RoomRecordingView;
+  readonly nameOf: NameOf;
+  readonly action: RecordAction;
+  readonly onRecordControl: () => void;
+}
+
+function actionFor(recording: RoomRecordingView, nameOf: NameOf): RecordAction {
+  if (recording.recordingHere) return { kind: "stop" };
+  if (recording.requesting) return { kind: "withdraw" };
+  const { state } = recording;
+  if (state.status === "remote-recording") {
+    return { kind: "blocked", reason: `${nameOf(state.recorder)} is already recording.` };
+  }
+  if (state.status === "prompted") return { kind: "blocked", reason: RECORD_COPY.busyPrompted };
+  if (recording.support === "unsupported") {
+    return { kind: "blocked", reason: RECORD_COPY.unsupported };
+  }
+  return { kind: "request" };
+}
+
+/** Announces the indicator turning on (who records) and off, never on the first render. */
+function useIndicatorAnnouncements(recording: RoomRecordingView, announce: Announce): void {
+  const { indicatorOn, recordingHere } = recording;
+  const previous = useRef(indicatorOn);
+  useEffect(() => {
+    if (previous.current === indicatorOn) return;
+    previous.current = indicatorOn;
+    if (!indicatorOn) announce(RECORD_COPY.stopped);
+    else announce(recordingHere ? RECORD_COPY.startedHere : RECORD_COPY.startedElsewhere);
+  }, [indicatorOn, recordingHere, announce]);
+}
+
+/** Announces each new one-time notice (the note itself is aria-live="off"). */
+function useNoticeAnnouncements(
+  recording: RoomRecordingView,
+  nameOf: NameOf,
+  announce: Announce,
+): void {
+  const { notice } = recording;
+  const previous = useRef(notice);
+  useEffect(() => {
+    if (previous.current === notice) return;
+    previous.current = notice;
+    if (notice !== null) announce(noticeText(notice, nameOf));
+  }, [notice, nameOf, announce]);
+}
+
+export function useRecordingUi(snapshot: RoomSnapshot, announce: Announce): RecordingUi {
+  const recording = useRoomRecording();
+  const { local, remotes } = snapshot;
+  const nameOf = useMemo(
+    () => namesFrom(local === null ? remotes : [local, ...remotes]),
+    [local, remotes],
+  );
+  useIndicatorAnnouncements(recording, announce);
+  useNoticeAnnouncements(recording, nameOf, announce);
+  const action = actionFor(recording, nameOf);
+
+  const onRecordControl = () => {
+    switch (action.kind) {
+      case "stop":
+        recording.stop();
+        return;
+      case "withdraw":
+        recording.withdraw();
+        announce(RECORD_COPY.withdrawn);
+        return;
+      case "blocked":
+        announce(action.reason);
+        return;
+      case "request": {
+        const result = recording.request();
+        announce(result.ok ? RECORD_COPY.asked : requestErrorText(result.error));
+        return;
+      }
+    }
+  };
+
+  return { recording, nameOf, action, onRecordControl };
+}
